	(101, 1, '앉아', '기본 자세부터 차근차근', '간식으로 앉는 자세를 만든 뒤 "앉아"라는 말을 붙여요.
INSERT INTO "curriculums" ("id", "topic_id", "title", "sort_order", "thumbnail_url", "description", "created_at", "updated_at") VALUES
	(10101, 101, '간식으로 앉아 만들기', 1, '', '간식을 따라 앉는 자세를 만든 뒤 "앉아"라는 말을 붙여요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10102, 101, '어디서든 앉아 다듬기', 2, '', '눈맞춤과 양손 보상을 더해 어떤 장소에서도 앉을 수 있게 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10201, 102, '먹이 앞에서 잠깐 참기', 1, '', '앉은 자세에서 보상을 기다리는 첫 경험을 만들어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10202, 102, '방석 위에서 기다리기', 2, '', '방석을 좋은 자리로 만들고 보호자가 움직여도 머물게 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10203, 102, '기다리는 시간과 거리 늘리기', 3, '', '릴렉세이션 프로토콜에 따라 시간과 거리를 하나씩 늘려요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10204, 102, '문 앞에서 기다리기', 4, '', '문이 열려도 보호자의 허락을 기다리는 습관을 만들어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10205, 102, '공원에서 거리 두고 기다리기', 5, '', '지나가는 사람과 소리 속에서도 자리를 지키는 연습이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10301, 103, '배변 원리 이해와 환경 준비', 1, '', '강아지가 화장실을 고르는 기준을 알고 집을 준비해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10302, 103, '좋아하는 장소부터 만드는 패드 기본', 2, '', '약 7일 동안 진행해요. 패드보다 편안한 자리를 먼저 알려 줘요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10303, 103, '하루 배변 루틴 만들기', 3, '', '약 7일 뒤부터 꾸준히 이어 가요. 타이밍과 보상, 실수 대응을 익혀요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10304, 103, '크레이트를 활용한 집중 배변 훈련', 4, '', '약 60일 동안 진행해요. 켄넬 주제를 먼저 마쳐야 시작할 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10305, 103, '배변 상황별 선택 훈련', 5, '', '우리 강아지에게 해당하는 상황만 골라 연습하는 단계예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10401, 104, '무는 이유 이해하기', 1, '', '읽으면서 무는 행동의 원리를 먼저 이해하는 단계예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10402, 104, '물어도 되는 환경 만들기', 2, '', '약 5~60일 동안 진행해요. 물어도 되는 대상을 분명히 정해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10403, 104, '놀이로 무는 욕구 풀기', 3, '', '약 5~30일 동안 진행해요. 쫓고 무는 욕구를 놀이로 발산해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10404, 104, '멈추는 신호 가르치기', 4, '', '약 7~10일 동안 진행해요. 놀이로 욕구를 푸는 단계와 함께해야 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10405, 104, '만지면 세게 무는 전환기', 5, '', '쓰다듬으면 힘껏 무는 시기를 지나는 강아지를 위한 단계예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10406, 104, '사람이 좋아서 무는 강아지', 6, '', '반가움을 입으로 표현하는 강아지를 위한 단계예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10501, 105, '사회화 골든타임', 1, '', '약 30~60일 동안 진행해요. 평생을 좌우하는 시기를 놓치지 않아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10502, 105, '실내 자극 둔감화', 2, '', '약 14일 동안 진행해요. 소리와 물건, 손길에 차례로 익숙해져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10503, 105, '목줄과 가슴줄 둔감화', 3, '', '약 14일 동안 진행해요. 장비를 보고 피하지 않도록 천천히 익혀요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10504, 105, '낯선 사람과 인사하기', 4, '', '약 7~30일 동안 진행해요. 사람이 다가가지 않는 인사법을 익혀요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10505, 105, '사람 인사 상황별 선택 훈련', 5, '', '우리 강아지의 성향에 맞는 상황만 골라 연습하는 단계예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10506, 105, '다른 강아지와 인사하기', 6, '', '약 14~21일 동안 진행해요. 시각과 후각, 동행의 3단계로 인사해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10507, 105, '강아지 관계 상황별 선택 훈련', 7, '', '또래 만남과 합사처럼 해당하는 상황만 골라 연습해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10601, 106, '혼자 있는 환경 만들기 (입문 · 14일)', 1, '', '', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10602, 106, '방석 교육 (입문 · 14일)', 2, '', '', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10603, 106, '안정화 교육 (기초 · 14일)', 3, '', '', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10604, 106, '다녀올게 신호와 콩토이 (심화 · 14일)', 4, '', '', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10605, 106, '심한 분리불안 집중 교정 (선택)', 5, '', '', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10701, 107, '실내에서 줄 적응하기', 1, '', '집 안에서 목줄과 리드줄에 먼저 익숙해지는 단계예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10702, 107, '먹이줄로 시작하는 첫 산책', 2, '', '줄을 매고 걷는 것 자체를 즐거운 경험으로 만들어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10703, 107, '바깥 자극에 적응하기', 3, '', '접종 전후 상황에 맞춰 안전한 거리에서 바깥을 경험해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10704, 107, '보호자 집중과 줄당김 잡기', 4, '', '자극에 쏠린 집중을 보호자에게 나누고 줄당김을 줄여요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10705, 107, '옆에 걷기와 앉아 유지', 5, '', '보호자 옆에서 걷고 신호가 올 때까지 자세를 유지해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10706, 107, '산책 예절 익히기', 6, '', '생후 4개월 무렵부터 시작해요. 사람과 강아지를 배려하며 걸어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10707, 107, '산책 상황별 선택 훈련', 7, '', '주저앉기와 두려움처럼 해당하는 상황만 골라 연습해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10801, 108, '켄넬 배치와 자발적 탐색', 1, '', '켄넬을 놓을 자리를 정하고 스스로 살펴보게 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10802, 108, '간식으로 드나들기', 2, '', '갇히는 곳이 아니라 자유롭게 드나드는 곳으로 느끼게 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10803, 108, '켄넬 안의 좋은 경험 쌓기', 3, '', '가장 좋아하는 간식과 장난감으로 머무는 시간을 늘려요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10804, 108, '켄넬 문 닫기 연습', 4, '', '나오고 싶어 하기 전에 문을 열어 편안한 경험으로 끝내요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10805, 108, '하우스 신호 붙이기', 5, '', '확실해진 동작에 "하우스"라는 말 신호를 연결해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10901, 109, 'V 손신호에 턱 올리기', 1, '', '손바닥 턱받침에서 시작해 V 손신호까지 연결해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(10902, 109, '빵야에 옆으로 눕기', 2, '', '편안한 옆으로 눕기를 만든 뒤 "빵야" 신호를 붙여요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
