INSERT INTO "cards" ("id", "lesson_id", "title", "sort_order", "instruction", "created_at", "updated_at") VALUES
	(101010101, 1010101, '흥분을 가라앉히는 평생 신호', 1, '앉아는 산책이나 갑작스러운 상황에서 흥분을 가라앉힐 때 쓰는 신호예요. 앞으로 가장 자주 쓰게 될 기본 신호이기도 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010102, 1010101, '조용한 방과 작은 간식', 2, '주변 자극이 적은 조용한 방에서 작은 간식을 준비해 주세요. 가족 모두가 "앉아"라는 같은 단어를 쓰면 강아지가 덜 헷갈려요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010103, 1010101, '코앞에서 머리 뒤로 이어지는 유도', 3, '간식을 강아지 코앞에 가져간 뒤 머리 위쪽으로 천천히 들어 올려 주세요. 그대로 머리 뒤쪽으로 옮기면 고개를 따라 들다가 자연스럽게 주저앉아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010104, 1010101, '앉는 순간의 보상 타이밍', 4, '엉덩이가 바닥에 닿는 바로 그 순간 간식을 주세요. 이미 앉아 있다면 그 순간을 그대로 보상해도 좋아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010105, 1010101, '보상 전 손길 금지', 5, '아무리 잘했어도 먹이를 주기 전에 만지는 것으로 보상하지 마세요. 손길이 먼저 오면 앉는 행동과 보상의 연결이 흐려져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010106, 1010101, '점프할 때의 대처', 6, '강아지가 점프하면 엉덩이를 살짝 밀어 앉도록 도와주세요. 엉덩이를 세게 누르거나 큰 소리로 강요하면 앉기 자체를 싫어할 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010107, 1010101, '루어를 따라 매번 앉으면 다음 레슨', 7, '간식을 머리 위로 올릴 때마다 자연스럽게 앉는다면 다음 레슨으로 넘어가세요. 이어서 동작에 말을 붙이는 연습을 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010201, 1010102, '동작에 말을 입히는 단계', 1, '이미 나오는 동작에 단어를 입히는 단계예요. 명령으로 없던 동작을 만들어 내는 것이 아니에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010202, 1010102, '앉는 타이밍에 말하는 앉아', 2, '엉덩이가 내려가는 바로 그 순간에 "앉아"라고 말해 주세요. 말과 함께 칭찬하고 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010203, 1010102, '빈손에서 말만으로', 3, '간식 없이 빈손으로 유도해 보고, 익숙해지면 "앉아"라는 말만으로 앉게 해 주세요. 간식을 얻을 수 있다는 기대감만으로도 앉게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010204, 1010102, '생후 2개월의 연습 방법', 4, '생후 2개월이면 아직 명령어를 알아듣지 못해요. 먹이를 코 위로 들어 앉으면 그냥 주는 식으로 자세만 경험시키고, 3개월부터 말을 붙여 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010205, 1010102, '말만으로 앉으면 다음 과정', 5, '간식으로 유도하지 않아도 "앉아"라는 말에 앉을 수 있다면 다음 과정으로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020101, 1010201, '앉아의 완성인 눈맞춤', 1, '앉아와 기다려는 그냥 앉히는 것이 아니에요. 앉은 채 보호자와 눈이 마주쳐야 흥분이 가라앉는, 모든 교육의 기초예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020102, 1010201, '코앞에 간식을 들고 있는 실수', 2, '간식을 든 채 강아지 코앞에 붙어 있지 마세요. 훈련이 아니라 먹을 것에 대한 흥분만 키워요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020103, 1010201, '움직이며 앉히고 뻗는 손', 3, '보호자가 움직이면서 강아지를 앉혀 주세요. 앉으면 간식 든 손을 옆으로 쭉 뻗고 가만히 두었다가, 손이 아니라 보호자 눈을 쳐다보는 순간 간식을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020104, 1010201, '떨어졌다 돌아오는 연습', 4, '눈맞춤이 되면 강아지에게서 잠시 떨어졌다가 돌아오는 연습을 해 주세요. 조금 떨어져도 다시 온다는 믿음이 쌓이면 초인종과 손님 상황, 분리불안 교육의 바탕이 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020105, 1010201, '몰아붙이는 말투 주의', 5, '"앉아, 기다려" 하고 몰아붙이지 마세요. 주눅 들게 만드는 것은 진정이 아니에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020106, 1010201, '짖음 교정으로 이어지는 기초', 6, '앉은 채 보호자와 눈을 맞추고, 잠시 떨어져도 기다릴 수 있으면 잘하고 있는 거예요. 이 기초가 있으면 짖음과 흥분을 다루는 교육도 훨씬 수월해져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020201, 1010202, '양손을 번갈아 주는 간식', 1, '간식을 한 손으로만 주지 말고 양손을 번갈아 주세요. 오른손으로만 연습하면 왼손 신호에는 반응하지 못하는 경우가 많아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020202, 1010202, '정확히 앉는 순간만 보상', 2, '약간 단이 높은 곳이나 방석 위에서 연습해 주세요. 앉아와 엎드려를 한 번에 해 버리는 강아지라면 정확히 앉는 순간에만 보상해 두 행동을 구분해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020203, 1010202, '한 손은 간식, 한 손은 터치', 3, '한 손으로 간식을 주면서 다른 손으로 몸을 만져 주세요. 몸에 닿는 손길에 대한 부담을 낮추는 연습이 함께 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020204, 1010202, '짖을 때 보상 금지', 4, '답답해서 짖는 강아지가 있어요. 짖을 때 놀라서 간식을 주면 짖는 행동을 가르치게 되니, 원하는 자세가 나올 때만 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020205, 1010202, '양손 어느 쪽이든 유지되는 자세', 5, '왼손과 오른손 어느 쪽으로 유도해도 앉고, 몸을 만지는 동안 자세를 유지하면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020301, 1010203, '산만한 곳으로 확장', 1, '집에서 충분히 되면 공원처럼 사람이 많은 곳에서 같은 방법으로 연습해 주세요. 장소만 바꾸고 방법은 그대로 유지해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020302, 1010203, '흥분 상황에서의 실전 사용', 2, '산책처럼 흥분하기 쉬운 상황에서도 "앉아"를 써 보세요. 보호자에게 집중하며 차분해지는 것이 이 신호의 목적이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020303, 1010203, '칭찬과 보상으로만 연습', 3, '낯선 장소에서도 강압하지 말고 칭찬과 간식으로 연습해 주세요. 편안한 경험이 쌓여야 어디서든 안정적으로 앉을 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020304, 1010203, '낯선 환경에서도 앉으면 완료', 4, '낯선 환경에서도 말만 듣고 앉을 수 있으면 앉아 교육을 마친 거예요. 이후에는 엎드려를 이어서 연습해 보세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010101, 1020101, '바로 주지 않는 것이 기다려의 시작', 1, '앉을 줄 아는 강아지에게 앉았다고 먹이를 바로 주지 말고 잠깐 들고 있어 주세요. 이 참는 순간이 기다려의 시작이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010102, 1020101, '앉아가 되는 상태와 손 안의 먹이', 2, '앉아가 먼저 되는 상태에서 시작해 주세요. 사료나 한입 크기 간식을 손에 쥐고 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010103, 1020101, '보호자가 정하는 보상 타이밍', 3, '강아지가 스스로 일어나기 전에, 보호자가 정한 순간에 먹이를 주세요. 강아지가 먼저 일어나 보상을 가져가게 두지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010104, 1020101, '먹이를 줄 때까지 유지하는 자세', 4, '앉거나 엎드린 상태에서 시간을 조금씩 늘리고, 먹이를 줄 때까지 스스로 움직이지 않게 해 주세요. 한 번 끝나면 가볍게 터치해 자세를 초기화하고 다시 기다리게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010105, 1020101, '힘들어할 때의 조절', 5, '기다리는 동안 숨이 잠시 가빠질 수 있어요. 힘들어하면 시간을 줄이고, 억지로 버티게 하지 말고 짧게 성공하는 경험부터 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010106, 1020101, '보상까지 앉아 있으면 다음 단계', 6, '보호자가 간식을 줄 때까지 앉은 자세를 유지하면 잘하고 있는 거예요. 다음 단계에서는 이 행동에 "기다려"라는 말을 붙여요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010201, 1020102, '해제어 전까지의 정지', 1, '이 단계의 목표는 해제하는 말을 듣기 전까지 움직이지 않는 거예요. 참는 시간을 스스로 견디는 힘을 기르는 과정이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010202, 1020102, '앉히고 말하는 기다려 2초', 2, '강아지를 앉히고 "기다려"라고 말한 뒤 2초 동안 가만히 바라봐 주세요. 2초를 앉아 있으면 칭찬하고 작은 간식을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010203, 1020102, '한 걸음 물러났다 돌아와 보상', 3, '숙달되면 "기다려" 뒤에 한 걸음 물러났다가 다시 다가가 칭찬하고 보상해 주세요. 두세 걸음까지 늘리며 시간과 거리를 조금씩 넓혀 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010204, 1020102, '끝을 알려주는 해제어', 4, '충분히 숙달되면 "쉬어" 같은 해제 단어를 정해 말해 주세요. 더 이상 기다리지 않아도 된다는 것을 분명히 알려 주는 신호예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010205, 1020102, '하루 2번, 한 번에 5분 이내', 5, '하루 2번 정도, 한 번에 5분을 넘기지 않게 해 주세요. 10분이 넘어가면 집중하지 못해 교육 효과가 떨어져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010206, 1020102, '해제 신호까지 기다리면 다음 단계', 6, '2초도 기다리기 어렵다면 시간을 더 짧게 줄여 성공부터 만들어 주세요. 해제 신호 전까지 편안하게 기다릴 수 있으면 다음 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020101, 1020201, '자리를 찜해 두는 기다림', 1, '기다려는 명령으로 억누르는 것이 아니에요. 방석 위에서 잠깐 대기하는 것을 알려 주는 과정이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020102, 1020201, '방석과 좋아하는 간식', 2, '편안하게 머물 수 있는 방석과 좋아하는 간식을 준비해 주세요. 특별한 장비보다 강아지가 좋아하는 보상이 중요해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020103, 1020201, '방석 위에서 주는 두 가지 보상', 3, '방석 위에 간식을 미리 놓아 우연히 찾아 먹게 해 주세요. 강아지가 방석에 올라올 때는 손으로도 직접 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020104, 1020201, '부르지 않는다는 원칙', 4, '"이리 와"라고 부르지 마세요. 특히 어린 강아지는 부를수록 통제받는다고 느껴요. 다른 곳을 오갈 때는 보상하지 말고 방석 위에서만 간식이 나오게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020105, 1020201, '올라가 머무는 순간의 보상', 5, '부르지 말고 스스로 방석에 올라가기를 기다려 주세요. 방석 위에 머무는 순간 바로 칭찬하고 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020106, 1020201, '스스로 올라오면 심화 단계', 6, '부르지 않아도 스스로 방석에 올라가 잠깐 머물 수 있으면 다음 단계로 넘어가세요. 어린 강아지는 집중 시간이 짧으니 짧게 끝내도 괜찮아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020201, 1020202, '동작을 멈추고 대기하는 신호', 1, '기다려는 하던 동작을 멈추고 그 자리에서 잠깐 대기하는 신호예요. 자리를 지키는 것 자체가 목표예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020202, 1020202, '하나씩 주며 늘리는 대기 시간', 2, '방석 위에서 간식을 하나씩 주며 머무는 시간을 늘려 주세요. 보호자가 일어서거나 한 걸음 물러나도 방석에 있으면 다시 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020203, 1020202, '따라와도 무반응', 3, '보호자가 다른 곳으로 이동할 때 오라고 부르지 마세요. 쪼그려 앉는 자세도 오라는 신호가 되니 주의해 주세요. 따라왔다면 간식을 주지도, 크게 칭찬하지도 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020204, 1020202, '방석 쪽으로 걸어가 주는 보상', 4, '강아지가 방석에 머물러 있으면 보호자가 방석 쪽으로 다가가 보상해 주세요. 강아지를 불러 움직이게 하지 않는 것이 중요해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020205, 1020202, '손바닥을 보이며 다가가는 방법', 5, '숙련되면 거리를 조금 더 벌려 주세요. 다가갈 때는 무릎을 강아지 쪽으로 향하고 손바닥을 계속 보여주면서 가까이 가 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020206, 1020202, '잠깐의 대기가 되면 충분', 6, '보호자가 조금 떨어져도 방석에서 잠깐 기다릴 수 있으면 충분히 잘한 거예요. 짧은 대기부터 일관되게 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030101, 1020301, '시간과 거리, 강도라는 세 요소', 1, '간식 앞에서만 참는 것은 기다려의 일부분이에요. 시간과 거리를 따로따로 늘려야 어디서든 통하는 기다려가 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030102, 1020301, '딱 한 번만 말하는 기다려', 2, '"기다려"라고 한 번만 명확하게 말해 주세요. 여러 번 반복하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030103, 1020301, '가는 척했다 돌아와 주는 옳지', 3, '한 발짝을 다 가지 말고 가는 척만 했다가 바로 돌아서서 "옳지" 하고 보상해 주세요. 다섯에서 열 번 반복하되, 보상할 때는 허리 대신 무릎을 숙여 점프를 막아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030104, 1020301, '2초에서 5초로 늘리는 시간', 4, '거리는 가까이 둔 채 2초 앉아 있기부터 시작하고, 되면 5초로 늘려 주세요. "옳지" 이후에는 한 박자 쉬고 손을 움직여 간식을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030105, 1020301, '실패했을 때의 난이도 조절', 5, '움직였다면 강아지가 못하는 것이 아니라 난이도를 너무 올린 거예요. 성공했던 짧은 시간으로 되돌리고, 싫어하는 기색이 보이면 그날은 거기서 끝내 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030106, 1020301, '시간이 견뎌지면 거리 연습', 6, '2초에서 5초 동안 편안하게 기다릴 수 있으면 거리 연습으로 넘어가세요. 시간과 거리를 한꺼번에 늘리지 말고 한 가지씩 조절해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030201, 1020302, '한 발자국에서 세 발자국까지', 1, '"기다려" 뒤에 한 발자국 갔다가 돌아와 "옳지" 하고 보상해 주세요. 되면 두 발자국, 세 발자국으로 거리만 늘리고, 세 발자국에서는 5초를 세고 돌아와 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030202, 1020302, '움직이면 직전 수준으로', 2, '세 발자국에서 5초를 못 견디고 움직였다면 시간을 너무 많이 올린 거예요. 두 발자국으로 돌아가거나 세 발자국에서 3초로 낮춰 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030203, 1020302, '등 돌리기와 한 바퀴 돌기 변형', 3, '정면을 보며 좌우로 가기, 벽을 터치하고 오기, 강아지 주위를 한 바퀴 돌기 같은 변형을 조금씩 쪼개서 성공시켜 주세요. 등을 완전히 보이면 실패하기 쉬우니 처음에는 정면을 보면서 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030204, 1020302, '시야에서 잠깐 사라졌다 복귀', 4, '문을 열고 아주 잠깐 사라졌다가 바로 돌아와 "옳지" 하고 보상해 주세요. 사라져 있는 시간을 조금씩 늘리되, 이미 "옳지"를 말했다면 그 뒤에 실수해도 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030205, 1020302, '온 가족이 여러 공간에서', 5, '하루 5분씩 두 번, 훈련이 아니라 놀이처럼 해 주세요. 가족 모두가 돌아가며 거실과 안방, 조용한 야외로 장소를 옮겨 가면 효과가 가장 좋아요. 자리를 뜨고 냄새를 맡으면 쉬고 싶다는 신호이니 쉬게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030206, 1020302, '3개월에 걸친 15개 과제', 6, '릴렉세이션 프로토콜의 과제를 약 3개월 동안 천천히 익혀 보세요. 서두르지 않고 반복하면 일상에서 흥분을 조절하는 데 도움이 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040101, 1020401, '나가는 것 자체가 보상', 1, '문이 열리자마자 튀어나가는 것은 위험해요. 이 단계의 보상은 간식이 아니라 밖으로 나가는 것 자체예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040102, 1020401, '문 대각선에 서는 위치', 2, '목줄을 채우고 문이 열리는 쪽 대각선에 서 주세요. 강아지가 나가려 할 때 몸으로 막을 수 있는 위치예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040103, 1020401, '움직이면 바로 닫는 문', 3, '앉아와 기다려를 시키고 문을 조금씩 열어 주세요. 강아지가 움직이면 문을 즉시 닫고 앉아부터 다시 시작하고, 줄에 가벼운 텐션을 줘도 좋아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040104, 1020401, '다 열려도 기다리면 출발', 4, '문이 다 열려도 기다리고 있으면 그때 "옳지"라고 말하고 함께 나가 주세요. 나가는 것이 보상이 되는 순간이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040105, 1020401, '방문에서 공동현관까지 확장', 5, '집 안 방문에서 먼저 연습하고 현관문, 엘리베이터 순으로 넓혀 주세요. 가능하다면 아파트 공동현관까지 같은 방식으로 확장해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040106, 1020401, '허락을 기다리면 낮아지는 흥분', 6, '문이 열려도 보호자의 허락이 있어야 나갈 수 있다는 인식이 생기면 흥분도가 떨어져요. 문이나 엘리베이터에서 갑자기 튀어나가 다른 사람이 놀라는 일도 막을 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040201, 1020402, '문 안에서 절반, 밖에서 절반', 1, '문을 열어 놓고 기다리게만 한 뒤 그냥 나가는 것은 절반짜리 연습이에요. 문 안에서 절반, 나와서 절반이 채워져야 완성돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040202, 1020402, '기다려 다음에 오는 나와', 2, '문을 열고 "기다려"를 시켜 주세요. 튀어나가려는 충동을 참게 한 뒤 "나와"라고 말해 문을 넘어오게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040203, 1020402, '나오자마자 다시 기다려', 3, '문을 넘어오면 바로 다시 "기다려"를 시켜 주세요. 안과 밖의 흥분 차이를 한 번 끊어준 다음 "가자"로 출발해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040204, 1020402, '안팎 모두 기다리면 완료', 4, '문 안과 밖에서 모두 기다릴 수 있으면 이번 단계를 마친 거예요. 다음에는 공원처럼 자극이 있는 곳에서 거리를 두고 기다리는 연습을 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050101, 1020501, '산책보다 먼저인 공원 기다려', 1, '산책 교육을 따라 해도 잘 되지 않는 강아지가 있어요. 산책보다 먼저, 사람들이 지나다니는 공원에서 떨어져 기다리는 힘을 만들어야 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050102, 1020501, '바닥 선이 있는 놀이터 근처', 2, '목줄과 간식을 챙기고 바닥에 타일 선이 있는 공간을 골라 주세요. 놀이터 근처가 좋은데, 아이들의 빠른 움직임이 적당한 자극이 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050103, 1020501, '한 칸씩 벌리는 거리', 3, '타일 선을 경계로 "기다려"를 시키고 보호자가 한 칸 나가 주세요. 선을 넘지 않으면 "옳지"와 함께 보상하고, 그다음 두 칸으로 넓혀 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050104, 1020501, '선을 넘었을 때의 복귀', 4, '선을 넘어 따라 나오면 "안돼" 하고 처음 기다리던 자리로 정확히 되돌려 주세요. 보호자 쪽으로 가까워진 자리가 아니라 원래 그 자리여야 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050105, 1020501, '손은 뒤로, 몸은 앞으로', 5, '자꾸 따라 나오면 신호를 준 손은 뒤쪽으로 뻗은 채 몸만 앞으로 나가 주세요. 손으로 기다려 신호를 확실히 주면서 몸이 먼저 거리를 벌리는 방식이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050106, 1020501, '선을 넘지 않으면 다음 단계', 6, '한두 칸 떨어진 거리에서도 기준선을 넘지 않고 기다릴 수 있으면 다음 단계로 넘어가세요. 보호자와 떨어져 안정적으로 기다리는 경험을 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050201, 1020502, '한 자리에 고정하는 신호 손', 1, '"기다려" 신호를 준 손은 그 위치에 고정해 주세요. 강아지가 방향을 돌아도 손이 따라가지 않게 하고 보호자의 몸만 움직여 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050202, 1020502, '쳐다보는 순간의 칭찬', 2, '기다리던 강아지가 보호자를 쳐다보면 그 순간 "옳지"라고 말하고 칭찬과 간식을 주세요. 계속 주시하게 만드는 보상이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050203, 1020502, '초기화 신호가 되는 가벼운 터치', 3, '자극에 두리번거리면 몸을 가볍게 터치해 주세요. 자극을 빨리 잊고 다시 집중하게 하는 신호예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050204, 1020502, '보상하러 갈 때 움직이면 무효', 4, '보상을 주러 다가가는데 강아지가 움직이면 그 보상은 성립하지 않아요. "기다려"를 다시 시키고 가만히 기다린 상태에서 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050205, 1020502, '주시하며 자리를 지키면 다음 단계', 5, '거리를 둔 상태에서도 보호자를 바라보며 자리를 지킬 수 있으면 다음 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050301, 1020503, '사람이 지나간 뒤에 주는 간식', 1, '사람이 지나가는 동안 기다리게 하고 완전히 지나간 뒤 간식을 주세요. 보상 후에는 다시 기다리는 자세로 돌아가 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050302, 1020503, '함께 늘리는 거리와 유혹', 2, '보호자와의 거리를 조금 더 벌리고 주변 움직임도 하나씩 추가해 주세요. 강아지가 기준선을 넘기 전에 미리 신호를 주는 타이밍을 익혀 보세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050303, 1020503, '마무리에 쏟아붓지 않는 간식', 3, '마무리한다고 간식을 한꺼번에 많이 주며 끝내지 마세요. 마지막까지 같은 기준으로 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050304, 1020503, '자극과 진정의 반복이 완성 기준', 4, '간헐적으로 오는 자극 속에서 자극과 진정이 반복되며 자리를 지키면 완성이에요. 이 연습 자체가 보호자와 반려견 사이 신뢰의 척도예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010101, 1030101, '냄새와 발바닥 감각으로 고르는 화장실', 1, '강아지는 냄새와 발바닥 감각으로 화장실을 구분해요. 소변 냄새가 남은 곳, 푹신한 촉감이 학습된 곳이 화장실이 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010102, 1030101, '집 안 전체가 화장실 후보', 2, '강아지에게는 집 안 사방이 화장실 후보예요. 지정된 한 곳에만 싸는 것은 어려운 일이고, 실수의 원인은 대부분 아직 끝나지 않은 교육이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010103, 1030101, '자는 곳에서 멀리 가려는 본능', 3, '자는 곳과 먹는 곳에서 최대한 멀리 배변하는 것이 본능이에요. 화장실 자리를 정할 때 이 점을 기억해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010104, 1030101, '완벽해지지 않는 배변 교육', 4, '배변 교육은 한 번에 완벽해지지 않아요. 실수했을 때 혼내면 불안이 커질 수 있으니 조용히 정리하고 다음 성공 기회를 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010201, 1030102, '잠자리에서 가장 먼 반대쪽', 1, '잠자리와 밥그릇, 물그릇을 한쪽에 두고 화장실은 가장 먼 반대쪽에 정해 주세요. 공간이 좁으면 몇 걸음이라도 떨어뜨려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010202, 1030102, '생활 구역 안에 넓게 까는 패드', 2, '처음에는 생활 구역 안에 패드를 넓게 깔아 주세요. 몸을 돌며 배변하는 강아지라면 큰 패드를 쓰고, 미끄러지지 않도록 바닥에 고정해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010203, 1030102, '한입에 먹을 수 있는 간식', 3, '한입에 먹을 수 있고 잘 잘라지는 간식을 준비해 주세요. 평소 먹는 사료도 훌륭한 보상이 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010204, 1030102, '무향 효소 탈취제 준비', 4, '향으로 덮는 방향제 대신 소변 냄새 성분을 분해하는 무향 효소 탈취제를 준비해 주세요. 냄새가 남으면 같은 자리에 또 배변해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020101, 1030201, '패드보다 먼저인 좋아하는 장소', 1, '어린 강아지에게는 패드보다 편안한 장소를 먼저 알려 주는 것이 좋아요. 방석과 한입 크기 간식을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020102, 1030201, '자고 먹고 쉬는 자리', 2, '방석 옆에서 간식을 손으로 주고 방석 틈에도 숨겨 스스로 찾아 먹게 해 주세요. 방석을 자고 먹고 쉬는 편안한 장소로 느끼게 하는 과정이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020103, 1030201, '방석 주변을 둥글게 감싸는 패드', 3, '방석 주변으로 패드를 둥그렇게 깔아 주세요. 위치는 보호자가 원하는 곳으로 정해도 괜찮아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020104, 1030201, '패드 쪽으로 오면 주는 간식', 4, '패드 쪽으로 오기만 해도 간식을 하나씩 주세요. 여기 가면 간식이 있다고 느끼는 정도가 목표이니, 패드 위에서 맛있게 먹고 재밌게 놀아 주고 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020105, 1030201, '다른 곳에 싸도 무반응', 5, '다른 곳에 배변해도 놀라거나 반응하지 마세요. 조용히 치우고 같은 연습을 다시 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020106, 1030201, '반복하면 찾아오는 성공의 순간', 6, '반복하다 보면 강아지가 패드에 배변하는 순간이 찾아와요. 강아지마다 속도가 다르니 며칠 동안 여유 있게 관찰해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020201, 1030202, '패드 성공이 알려주는 전환 시점', 1, '패드에 배변하는 성공이 시작되면 보상 방식을 바꿀 시점이에요. 이제 패드 위에 미리 두는 간식을 줄여 가요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020202, 1030202, '이제 그만두는 패드 위 간식', 2, '패드에 올라가는 습관이 붙었다면 패드 위에 간식을 미리 두지 마세요. 이제 패드는 먹는 자리가 아니라 배변하는 자리예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020203, 1030202, '손으로 직접 주는 보상', 3, '대신 패드에 올라가면 보호자가 손으로 직접 얼굴 앞에 먹이를 주세요. 보상이 바닥이 아니라 보호자에게서 나오게 바뀌는 단계예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020204, 1030202, '규칙이 바뀔 때의 긴장', 4, '규칙이 바뀌면 의심하거나 항의하듯 긴장할 수 있고, 긴장하면 그 자리에서 배설하기도 해요. 놀라지 말고 새 규칙을 차분히 유지해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020205, 1030202, '패드를 치울 때의 요령', 5, '밥을 줄 때처럼 패드를 치워야 한다면 간식을 주는 동안 천천히 치워 주세요. 갑자기 걷어 내면 자리 자체를 불안하게 느낄 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020206, 1030202, '배변 뒤 보호자를 보면 다음 단계', 6, '패드에 배변한 뒤 보호자를 바라보는 흐름이 자연스러워지면 다음 단계로 넘어가세요. 패드 위 간식은 처음 유도할 때만 짧게 쓰고 이후에는 패드 밖에서 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030101, 1030301, '배변 확률이 높은 순간', 1, '기상 직후, 식사나 물을 마신 뒤, 놀이가 끝난 뒤를 기억해 주세요. 바닥 냄새를 맡으며 빙빙 돌 때도 바로 화장실로 안내해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030102, 1030301, '강아지보다 먼저인 움직임', 2, '타이밍이 오면 강아지보다 먼저 움직여 패드 근처로 데려가 주세요. 패드에 올려두고 말을 걸기보다 옆에서 조용히 기다려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030103, 1030301, '올라간 것만으로 주지 않는 보상', 3, '패드에 올라간 것만으로 소리를 내거나 간식을 주지 마세요. 배변이 시작되면 끝까지 기다려야 하고, 빨리 반응하면 배변을 멈추거나 올라갔다 내려오기만 반복하게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030104, 1030301, '끝나는 순간의 짧은 칭찬', 4, '배변이 끝나는 순간 짧게 칭찬해 주세요. 간식은 패드 밖으로 한두 걸음 나오게 한 뒤 주어야 패드가 먹는 자리로 기억되지 않아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030105, 1030301, '칭찬과 패드 밖 간식이 습관이 되면 성공', 5, '배변이 끝난 직후 짧게 칭찬하고 패드 밖에서 간식을 주세요. 이 흐름이 자연스럽게 이어지면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030201, 1030302, '혼내지 않는 실수 대응', 1, '소리를 지르거나 코를 실수한 자리에 대게 하지 마세요. 시간이 지나면 강아지는 이유를 연결하지 못하니 무향 효소 탈취제로 조용히 닦아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030202, 1030302, '같은 자리 반복 실수의 대처', 2, '같은 자리에서 반복해서 실수하면 그 물건을 치우거나 접근을 막아 주세요. 이불이나 러그처럼 푹신한 물건은 촉감과 냄새가 배변 장소로 기억된 것이니, 치우고 냄새를 지운 뒤 주변에 패드를 넓게 다시 깔아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030203, 1030302, '자주 쓰는 패드 위치 파악', 3, '며칠 동안 기록해 자주 사용하는 패드 위치를 확인해 주세요. 덜 쓰는 패드부터 천천히 줄이고, 위치도 한 번에 멀리 옮기지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030204, 1030302, '실패가 늘면 마지막 성공 지점으로', 4, '패드를 줄이자 실패가 늘었다면 기준을 너무 빨리 바꾼 거예요. 마지막으로 성공했던 패드 수와 위치로 돌아가 며칠 더 유지해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040101, 1030401, '실내 생활 강아지와 크레이트 크기', 1, '실내에서만 생활하는 강아지를 위한 단계예요. 크레이트는 엎드려 쉬기에는 충분하지만 한쪽에 용변을 볼 수는 없을 만큼 약간 좁게 골라 주세요. 크레이트는 감금 도구가 아니라 강아지의 자기 방이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040102, 1030401, '아침에 깨면 바로 화장실로', 2, '아침에 깨면 즉시 크레이트 밖으로 꺼내 정해진 화장실로 데려가 주세요. 용변을 보는 순간 "쉬" 같은 짧은 신호음을 내고, 마치면 작은 간식이나 사료 한 알을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040103, 1030401, '배변하지 않으면 15분 뒤 다시', 3, '화장실에 데려갔는데 배변하지 않으면 다시 크레이트에서 15분 정도 쉬게 해 주세요. 배변할 때까지 같은 간격으로 차분히 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040104, 1030401, '낮 동안의 관찰과 반복', 4, '낮에는 계속 관찰하다가 냄새를 맡으며 돌아다니는 배변 신호가 보이면 즉시 화장실로 데려가 주세요. 깨어 있는 16시간 동안 여섯에서 여덟 번 정도 같은 루틴을 반복해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040105, 1030401, '신호음에 반응하기 시작하면 성공', 5, '배변할 때 들려주는 "쉬"라는 말에 자연스럽게 반응하기 시작하면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040201, 1030402, '잠들기 30분 전의 정리', 1, '잠자기 30분 전부터 물그릇과 밥그릇을 치워 주세요. 마지막으로 대소변을 보게 한 뒤 크레이트 문을 닫고 재워 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040202, 1030402, '3개월 이하 퍼피의 방광', 2, '생후 3개월 이하 퍼피는 방광 조절력이 약해 하룻밤을 참기 힘들 수 있어요. 밤중에 실수해도 혼내지 말고 조용히 정리해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040203, 1030402, '아침 루틴으로 이어지는 하루', 3, '아침에 일어나면 앞 레슨의 아침 루틴부터 다시 반복해 주세요. 매일 같은 순서를 지키는 것이 가장 중요해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040204, 1030402, '한두 주로 끝나지 않는 과정', 4, '한두 주 잘 가려도 끝난 것이 아니라 짧아야 한 달, 길면 몇 달이 걸려요. 오래 걸리는 것은 지능이 아니라 본능이 얼마나 강한지의 문제예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050101, 1030501, '푹신한 촉감을 패드로 착각하는 이유', 1, '카페트나 이불의 푹신한 촉감을 패드처럼 느껴 실수할 수 있어요. 비슷한 촉감의 물건을 잠시 치우고 패드 위치를 분명하게 알려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050102, 1030501, '카페트보다 두껍게 겹치는 패드', 2, '패드를 네다섯 장 겹쳐 카페트보다 두껍고 푹신하게 깔아 주세요. 이 기간에는 카페트와 발판을 치워 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050103, 1030501, '쓴 패드는 아래로, 새 패드는 위로', 3, '배변한 패드는 맨 아래로 옮겨 냄새가 남게 하고 새 패드를 위에 올려 주세요. 항상 다섯 장을 유지하며 일주일 정도 같은 방식으로 진행해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050104, 1030501, '일주일 뒤 카페트 복귀', 4, '일주일 뒤 카페트를 다시 깔고 패드를 배변 장소로 지정하는 연습과 함께 진행해 주세요. 실수한 자리에서 엎드리게 하고 칭찬하면 엎드린 곳이 배변 장소로 묶이니 주의해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050105, 1030501, '가장자리에 걸쳐 싸는 강아지', 5, '패드 가장자리에 걸쳐 배변한다면 방수 방석이나 낮은 박스로 테두리를 만들어 주세요. 강아지가 패드 범위를 쉽게 구분하도록 돕는 방법이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050106, 1030501, '혼내기 대신 환경 변화', 6, '혼내면 패드 자체를 거부할 수 있어요. 행동을 지적하는 대신 환경을 바꿔 성공하기 쉬운 조건을 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050201, 1030502, '싸고 싶은 자리가 확고한 강아지', 1, '배변 자리가 확고한 강아지도 있고, 그것은 정상이에요. 패드를 강요하기보다 다른 방법을 찾아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050202, 1030502, '하루 네 번의 산책', 2, '하루 네 번 산책으로 밖에서 배변하게 해 주세요. 하루 두 번으로는 부족해서 실내 패드 주변에 실수가 이어질 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050203, 1030502, '절충으로만 유지하는 실내 패드', 3, '실내 패드는 완전히 없애지 말고 절충하는 정도로 한 장 더 깔아 주세요. 그래도 옆에 배변할 수 있으니 여유를 두고 지켜봐 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050204, 1030502, '시간이 지나며 줄어드는 실내 배변', 4, '야외 배변이 자리 잡으면 본능적으로 집에서는 하지 않게 돼요. 조급해하지 말고 산책 횟수를 유지해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050301, 1030503, '혼내기의 중단', 1, '마킹을 혼내는 것을 즉시 멈춰 주세요. 제재할수록 강아지 입장에서는 불안과 반발이 커져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050302, 1030503, '안정감 부족과 갈등이라는 원인', 2, '마킹의 원인이 낯선 환경 때문인지, 보호자와의 갈등이나 불안 때문인지 먼저 살펴봐 주세요. 원인을 알아야 강아지에게 맞는 도움을 줄 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050303, 1030503, '제재가 아니라 관심과 놀이', 3, '마킹은 도움을 요청하는 신호라고 생각하고 관심과 놀이로 대응해 주세요. 함께 보내는 관찰 시간을 늘려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050304, 1030503, '산책만으로는 부족한 해결', 4, '마킹을 산책만으로 해결하려고 하지 마세요. 산책에서는 함께 뛰고 놀며 에너지를 건강하게 쓰는 데 집중해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050401, 1030504, '지나가는 시기의 행동', 1, '아기 때는 장난으로 자기 배설물을 먹기도 하는데 대부분 지나가는 행동이에요. 크게 걱정하지 않아도 괜찮아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050402, 1030504, '야외 배변으로 바꾸는 방법', 2, '가장 확실한 방법은 야외 배변으로 바꾸는 거예요. 하루에 한 번만이라도 밖에서 배변하게 하고 그 자리에서 바로 치워 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050403, 1030504, '소변만 봐도 좋은 외출', 3, '소변만 봐도 좋으니 자주 데리고 나가 주세요. 따로 교육하지 않아도 자연스럽게 줄어들어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050404, 1030504, '2주면 줄어드는 습관', 4, '2주만 이어가도 횟수가 줄거나 없어져요. 생후 4개월쯤 되면 집에서 거의 배변하지 않게 될 가능성이 커요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010101, 1040101, '고쳐야 할 버릇이 아닌 시기', 1, '아기 때 깨무는 것은 나쁜 버릇도, 반드시 고쳐야 하는 것도 아니에요. 훈육으로 접근하면 관계가 망가지고 예민한 성견이 될 수 있으니, 다만 사람 손을 무는 것으로 이 시기를 보내지는 않게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010102, 1040101, '좋아서 무는 대부분의 이유', 2, '무는 이유는 대부분 너무 좋고 관심이 많아서, 친근감을 표현하는 거예요. 악의가 있어서 무는 경우는 거의 없어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010103, 1040101, '없앨 수 없는 무는 욕구', 3, '무는 욕구는 없앨 수 없고 빠져나갈 길을 만들어 줘야 해요. 쫓아다니며 무는 욕구는 가만히 있는 장난감으로는 풀리지 않아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010104, 1040101, '입질을 키우는 리액션', 4, '"하지 마"라는 반응이 오히려 무는 행동을 강화해요. 발을 물었을 때 나오는 소리와 움직임은 강아지에게 놀이 시작 신호로 읽혀요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010105, 1040101, '5개월에 시작해 7개월에 끝나는 이갈이', 5, '이갈이는 생후 5개월쯤 시작해 7개월쯤 끝나요. 잔깨물기는 이갈이가 끝나면 대부분 사라지니 희망을 갖고 이어가 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020101, 1040201, '찢기는 나쁜 뜻이 아닌 놀이', 1, '패드나 벽지를 찢는 것은 나쁜 뜻이 아니라 노는 행동이에요. 물어도 되는 것을 따로 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020102, 1040201, '찢어도 되는 전용 장난감', 2, '물고 다니고 찢을 수 있는 장난감 몇 개를 따로 마련해 주세요. 그 장난감으로 놀 때는 개입하지 않고 차분히 지켜봐 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020103, 1040201, '치워 주는 반응의 금지', 3, '패드를 찢을 때 "하지 마" 하며 달려가 치워 주지 마세요. 그 반응 자체가 재미있어져서 더 자주 찢는 강아지가 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020104, 1040201, '조각을 삼킬 때의 교체', 4, '장난감 조각을 삼키려고 하면 즉시 크기나 재질을 바꿔 주세요. 삼킬 수 있는 작은 조각이 생기는 장난감은 쓰지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020105, 1040201, '허용된 장난감으로 푸는 욕구', 5, '허용된 장난감으로 찢고 무는 욕구를 풀 수 있으면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020201, 1040202, '발과 머리를 함께 쓰는 놀이', 1, '발과 머리를 함께 쓰는 놀이로 무는 욕구를 건강하게 풀어 주세요. 안 신는 신발이나 종이컵 안에 간식을 숨겨 시작해 보세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020202, 1040202, '신발과 옷, 종이컵 활용', 2, '신발 안에 간식을 넣어 뜯어 꺼내 먹게 해 주세요. 옷을 돌돌 말아 간식을 넣거나, 더 어렵게는 종이컵에 간식을 넣고 싸 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020203, 1040202, '처음에는 낮추는 난이도', 3, '처음에는 간식을 쉽게 꺼낼 수 있도록 물건을 살짝만 접어 주세요. 도움을 요청하면 조금 거들어 성공 경험을 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020204, 1040202, '손에 들지 않는 간식', 4, '보호자 손에 간식을 들고 있지 마세요. 간식은 물건 안에만 넣어 강아지가 스스로 풀게 하고, 다음 판은 천천히 냄새를 맡게 하며 다시 줘 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020205, 1040202, '생후 1개월부터 시작하는 놀이', 5, '생후 1개월부터 시작할 수 있고 이갈이가 끝난 뒤 두 달, 약 10개월에서 1년까지 매일 해 주세요. 짜증내며 손을 무는 것은 머리 쓰기가 잘 안 된다는 뜻이니 더 쉽게 만들어 다시 줘 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020206, 1040202, '신발을 줘도 뜯지 않는 시기', 6, '나중에는 신발을 물어뜯으라고 해도 뜯지 않고, 손을 입에 넣어도 물지 않는 시기가 와요. 그때까지 꾸준히 이어가 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020301, 1040203, '손과 물 것의 역할 구분', 1, '손과 물어도 되는 물건의 역할을 분명히 나눠 주세요. 식욕이 좋은 강아지라면 교육의 절반은 끝난 셈이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020302, 1040203, '내가 준 것만 물게 하는 기준', 2, '보호자가 준 물건을 물면 그대로 두세요. 주지 않은 물건을 물면 짧게 놀라게 해 멈추고, 손을 물면 허용된 다른 물건으로 시선을 돌려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020303, 1040203, '줄여야 할 손 깨물기 기억', 3, '손을 깨물며 노는 기억을 많이 남기지 말고 다른 것을 많이 물게 해 주세요. 손은 예뻐해 주는 것으로만 배우게 하는 것이 목표예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020304, 1040203, '이갈이와 함께 사라지는 잔깨물기', 4, '잔깨물기는 이갈이가 끝나면 대부분 자연스럽게 없어져요. 그때까지 기준을 일관되게 지켜 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030101, 1040301, '던져만 주는 놀이의 한계', 1, '장난감을 던져만 주고 알아서 놀게 하는 방식은 통하지 않아요. 강아지 입장에서는 어떻게 놀아야 할지 알 수 없어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030102, 1040301, '같이 뛰고 같이 쉬는 시간', 2, '보호자가 같이 뛰고 같이 놀고 같이 쉬어 주세요. 함께 논 시간이 쌓여야 안 되는 것을 알려 줄 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030103, 1040301, '노는 법이 아니라 멈추는 법', 3, '노는 중에 물면 받아 주고, 잠깐 멈추는 순간 "옳지" 하며 다시 놀아 주세요. 흥분 자체를 막는 것이 아니라 멈추는 법을 배우는 과정이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030104, 1040301, '이갈이 뒤에 옮기는 장소', 4, '이갈이가 끝나면 집에서 하던 무는 놀이를 밖에서만 하는 것으로 옮겨 주세요. 장소를 바꿔 주면 실내에서의 입질이 줄어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030201, 1040302, '무는 욕구를 빼 주는 통로', 1, '함께 당기고 놓아주는 놀이로 무는 욕구를 충분히 풀어 주세요. 강아지가 안전하게 물 수 있는 튼튼한 장난감을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030202, 1040302, '물게 하고 뺏겨 주기의 반복', 2, '장난감으로 계속 놀아 주며 물게 하고, 뺏어 주고, 다시 물게 하기를 반복해 주세요. 뺏는 것이 목적이 아니라 흐름을 이어 주는 것이 목적이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030203, 1040302, '놀이 중의 턱과 귀 터치', 3, '놀이 중 턱을 만져 주면 더 좋아하니 주둥이도 잡아 주고 귀도 간지럽혀 주세요. 이때 더 세게 무는 것은 정상 반응이고, 자고 있을 때도 장난감을 물고 있게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030204, 1040302, '최소 1년 이어가는 놀이', 4, '최소 1년은 이어가야 하고 끝나는 시점이 정해져 있지 않아요. 많이 해서 손해 보는 일은 없어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030205, 1040302, '계속할수록 줄어드는 손 깨물기', 5, '이 놀이를 계속할수록 손 깨물기와 여기저기 무는 행동이 줄어들어요. 이갈이 시기의 불편함도 함께 줄어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030301, 1040303, '쫓아가서 무는 놀이로만 풀리는 욕구', 1, '손이나 발을 쫓아 무는 강아지에게는 움직이는 장난감을 쫓는 놀이가 필요해요. 양말이나 행주처럼 한 번 쓰고 버릴 수 있는 것이 좋아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030302, 1040303, '낚시처럼 움직이는 양말과 행주', 2, '양말이나 행주를 낚시하듯 움직여 쫓아가 물게 해 주세요. 튼튼한 시판 장난감보다 한 번 갖고 놀고 버릴 것이 더 잘 맞아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030303, 1040303, '손발 깨물기를 줄이는 필수 놀이', 3, '손과 발을 깨물지 않게 하고 싶다면 반드시 해야 하는 놀이예요. 욕구를 충분히 발산시켜 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030304, 1040303, '놀이 다음에 오는 제지', 4, '충분히 놀아 무는 욕구를 푼 다음에 발을 무는 행동을 제지해 주세요. 놀이보다 제지를 먼저 하면 욕구가 남아 교육이 어려워져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030401, 1040304, '같은 방향을 보며 쌓는 신뢰', 1, '보호자와 같은 방향을 바라보며 함께 움직이는 놀이로 신뢰를 만들어 주세요. 장난감 두 개를 준비하면 흐름을 끊지 않고 이어갈 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030402, 1040304, '딸려가듯 당기는 방향', 2, '강아지가 장난감을 물면 무는 방향으로 딸려 가 주듯 뒤로 당겨 주세요. 힘으로 맞서지 말고 흐름을 따라가 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030403, 1040304, '가져가도 뺏지 않는 원칙', 3, '장난감을 가지고 가 버려도 쫓아가 뺏어오지 마세요. 다른 장난감을 보여주며 장난치고 그 사이 원래 장난감을 살짝 숨겨 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030404, 1040304, '물고 있는 동안의 터치와 방해', 4, '장난감을 무는 동안 얼굴과 몸을 부드럽게 만져 주세요. 가끔 살짝 밀어도 놀이를 이어가면 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030405, 1040304, '함께하는 즐거움을 알면 성공', 5, '장난감 놀이를 통해 보호자와 함께 활동하는 즐거움을 알게 되면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040101, 1040401, '멈칫하는 것까지가 목표', 1, '이번 단계의 목표는 짧은 소리에 잠깐 멈추는 것까지예요. 엎드리거나 반성하는 모습까지 요구하지 말고, 씹을 장난감과 간식을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040102, 1040401, '짧고 딱 떨어지는 소리', 2, '"압" 또는 "악"처럼 짧고 딱 떨어지는 소리를 써 주세요. "아이야" 하고 늘이는 소리는 효과가 없어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040103, 1040401, '혼내듯이 아니라 밝게', 3, '간식을 손에 쥐고 있다가 물면 "압" 하고 소리를 낸 뒤 간식을 주는 과정을 반복해 주세요. 혼내는 말투가 아니라 노는 것처럼 밝게 해야 통해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040104, 1040401, '더 흥분할 때는 씹을 거리로', 4, '소리에 흥분해 더 물면 혼내지 말고 씹을 거리로 전환해 주세요. 발 옆에 간식을 떨어뜨리고 이동해 또 떨어뜨리기를 반복하면 신발과 발 깨물기까지 조절돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040105, 1040401, '소리에 멈칫하면 성공', 5, '짧은 소리에 강아지가 잠깐 멈추면 잘하고 있는 거예요. 바로 칭찬하고 허용된 장난감으로 안내해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040201, 1040402, '리액션이라는 재미의 차단', 1, '발과 손, 옷을 무는 행동은 보호자의 리액션이 재미있어서 이어져요. 이번 단계에서는 그 재미를 끊어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040202, 1040402, '소리도 움직임도 없는 정지', 2, '물면 소리도 내지 말고 움직이지도 말고 죽은 듯 멈춰 주세요. 아무 반응이 없어야 놀이로 이어지지 않아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040203, 1040402, '아야와 하지 마가 주는 신호', 3, '"아야"나 "하지 마"는 터그 놀이의 시작 신호가 되어 무는 행동을 강화해요. 리액션을 완전히 끊고, 무는 욕구는 장난감 터그로 따로 재밌게 풀어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040204, 1040402, '흥미를 잃으면 조용한 전환', 4, '흥미를 잃고 그만두면 조용히 자리를 옮기거나 허용된 장난감으로 시선을 돌려 주세요. 이 흐름이 반복되면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040301, 1040403, '놀이보다 앞선 제지의 문제', 1, '놀이 없이 제지부터 하면 순서가 틀린 거예요. 욕구를 먼저 풀어 준 뒤에 멈추는 법을 알려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040302, 1040403, '신나게 논 다음의 짧은 신호', 2, '낚시 놀이로 신나게 논 다음, 일어나서 걸으려 할 때 발을 깨물려 하면 그 순간에만 가볍게 "아야" 하고 알려 주세요. 이 정도의 짧은 신호면 충분해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040303, 1040403, '타이밍이 전부인 이유', 3, '어린 강아지는 맥락 없이 혼내면 이유를 알지 못해요. 행동이 나온 그 순간에만 짧게 알려 주는 타이밍이 전부예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104050101, 1040501, '피가 날 만큼 세게 무는 시기', 1, '쓰다듬으면 피가 날 정도로 힘껏 무는 시기의 퍼피를 위한 단계예요. 무는 것을 멈추면 오히려 불안이 올라가는 전환기가 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104050102, 1040501, '강제 접촉 금지', 2, '이 시기에 강제로 만지거나 둔감화를 강하게 하면 관계가 깨져요. 당분간은 만지는 것 자체를 시도하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104050103, 1040501, '먹이와 함께 맡는 손냄새', 3, '대신 먹이를 주면서 손냄새만 맡게 해 주세요. 물거나 짜증내면 접촉을 멈추고 손냄새 맡기만 반복하며 강제하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104050104, 1040501, '스킨십을 싫어할 수도 있다는 준비', 4, '만지는 것을 평생 싫어하는 강아지도 많아요. 상상했던 스킨십을 하는 강아지가 아닐 수도 있다는 것을 받아들이면 관계가 더 편해져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104060101, 1040601, '반가움을 입으로 표현하는 강아지', 1, '사람이 너무 좋아 보호자 손가락을 무는 강아지를 위한 단계예요. 좋다는 표현이니 억누르지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104060102, 1040601, '같이 놀아 주는 것이 해소', 2, '손으로 가자는 동작을 하며 같이 놀아 주는 것이 해소예요. 이 손동작은 강아지에게 물어도 된다는 뜻이니, 시작했다면 무는 것을 받아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104060103, 1040601, '두 손이 아니라 한 손으로', 3, '두 손이 아니라 한 손으로만 놀아 주세요. 강아지가 배를 보이면 만지는 것을 줄여 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104060104, 1040601, '보호자도 누워서 하는 마무리', 4, '개들의 방식으로 마무리하려면 보호자도 함께 누워 주세요. 강아지가 엉덩이를 대는 것까지 받아 준 뒤 폴짝 일어나 도망가 주면 놀이가 이어져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104060105, 1040601, '놀이 중 냄새 맡기는 정상 반응', 5, '놀이 중 항문이나 생식기 냄새를 맡는 것은 너무 재밌다는 뜻이에요. 정상적인 반응이니 놀라지 않아도 괜찮아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105010101, 1050101, '생후 3주에서 12주라는 골든타임', 1, '사회화 시기는 생후 3주에서 12주 사이예요. 이 기간에 쌓은 좋은 경험이 평생을 좌우하고, 시기가 지나면 낯선 것에 두려움을 느끼기 시작해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105010102, 1050101, '접종 상태에 맞춘 바깥 경험', 2, '3개월령 전에는 수의사와 접종 상태를 확인하고, 접종 전에는 안거나 이동장으로 바깥을 경험하게 해 주세요. 건강이 확인된 개와 사람은 충분한 거리에서 짧고 편안하게 만나게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105010103, 1050101, '안고 나가는 어린 강아지의 산책', 3, '접종 전에는 수의사 지시에 따라 안거나 이동장을 쓰고 공공 바닥은 피해 주세요. 소음과 차, 사람은 멀리서 짧게 경험하고 불편해하기 전에 거리를 늘려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105010104, 1050101, '무서워하지 않는 강아지', 4, '이 시기를 잘 보내면 사물과 소리, 사람과 동물을 무서워하지 않는 강아지가 될 가능성이 크게 높아져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105010201, 1050102, '6개월 전에 만나는 100명', 1, '생후 6개월이 되기 전에 100명의 사람에게 먹이를 받아먹는 경험을 만들어 주세요. 숫자를 채우기보다 좋은 만남을 쌓는 것이 목적이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105010202, 1050102, '간식을 건네 달라는 부탁', 2, '강아지에게 관심을 보이는 사람에게 간식을 건네 달라고 부탁해 보세요. 하루에 서너 명이라도 좋은 만남을 꾸준히 경험하게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105010203, 1050102, '먹이와 함께 곁들이는 손길', 3, '먹이는 손으로 주고, 주는 동안 다른 손으로 살짝 만져 주는 연습도 조금씩 곁들여 주세요. 사람의 손을 좋은 것과 함께 기억하게 하는 과정이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105010204, 1050102, '손길과 사람에 대한 익숙함', 4, '낯선 사람의 손에서 먹이를 받고 가벼운 손길도 받아들이면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020101, 1050201, '참게 하는 것이 아닌 둔감화', 1, '둔감화는 자극을 억지로 참게 하는 교육이 아니에요. 한 번에 한 종류의 소리만 아주 작게 들려주며 안전하다는 느낌부터 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020102, 1050201, '멀리서 아주 작게 트는 소리', 2, '떨어진 곳에서 아주 작게 소리를 틀고, 소리 직전에 간식을 두어 소리가 나는 동안 계속 먹는지 봐 주세요. 먹기를 멈추면 소리를 줄이거나 더 멀리서 시작하고, 크기와 시간 중 하나만 조금씩 올려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020103, 1050201, '소리와 함께 시작하고 끝나는 간식', 3, '소리가 들리는 동안 간식을 주고 소리가 멈추면 간식도 멈춰 주세요. 소리와 좋은 경험이 연결되도록 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020104, 1050201, '도어락과 노크 같은 생활 소리', 4, '도어락이나 노크 같은 생활 소리는 쉬운 강도부터 따로 연습해 주세요. 청소기와 드라이어는 전원을 끈 상태에서 멀리 바라보는 것부터 시작해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020105, 1050201, '차분히 먹으면 올리는 강도', 5, '매트 위에서 차분하게 간식을 먹으면 자극을 조금만 키워 주세요. 몸이 굳거나 숨고 짖는다면 즉시 이전의 쉬운 단계로 돌아가 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020201, 1050202, '얼굴 앞으로 들이밀지 않는 물건', 1, '우산이나 박스, 냄비 같은 낯선 물건을 얼굴 앞으로 들이밀지 마세요. 조금 떨어진 바닥에 내려두고 스스로 살펴보게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020202, 1050202, '스스로 다가오면 주는 짧은 칭찬', 2, '스스로 냄새를 맡으러 오거나 한 걸음 다가오면 짧게 칭찬해 주세요. 필요하면 물건 근처 바닥에 사료를 한 알 놓아 스스로 다가가 먹고 빠져나오게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020203, 1050202, '반응에 따라 조절하는 거리', 3, '편하게 확인하면 조금 더 가까이 옮기고, 피하거나 멈추면 다시 멀리 두세요. 먹고 빠져나올 수 있을 만큼만 움직여 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020204, 1050202, '소리 나는 물건은 더 천천히', 4, '청소기나 드라이어처럼 소리 나는 물건은 꺼진 채 멀리 두고 근처에서 먹는지만 봐 주세요. 괜찮아진 뒤에야 아주 멀리서 짧게 켜 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020205, 1050202, '보기만 해도 도망갈 때', 5, '물건을 보기만 해도 도망간다면 크기와 움직임, 바람이 모두 부담스러운 상태예요. 작동시키지 말고 멀리서 보고 지나가는 연습부터 다시 시작해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020301, 1050203, '차분할 때 시작하는 손길', 1, '강아지가 차분할 때 시작해 주세요. 자는 강아지를 깨워 만지거나, 싫어하는데 계속 안고 있지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020302, 1050203, '머리 위가 아니라 어깨 옆으로', 2, '손을 먼저 보여준 뒤 가슴 옆이나 어깨를 1초만 부드럽게 만져 주세요. 편안하게 있으면 짧게 칭찬하고 작은 간식을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020303, 1050203, '1초에서 2초로 늘리는 접촉', 3, '1초 동안 편안하게 만질 수 있으면 2초에서 3초로 조금만 늘려 주세요. 피하거나 몸이 굳으면 다시 1초로 줄이고, 발과 귀는 몸통이 익숙해진 뒤에 만져 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020304, 1050203, '빗과 수건도 손길과 같은 순서로', 4, '빗이나 수건, 하네스도 먼저 바닥에 놓아 냄새를 맡게 해 주세요. 그다음 몸에 1초 닿았다가 떼는 짧은 경험부터 시작해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105020305, 1050203, '도구를 보고 피할 때', 5, '도구를 보고 피한다면 착용이나 관리는 아직 이른 단계예요. 바닥에 놓인 도구를 확인하기만 해도 칭찬하는 단계로 돌아가 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030101, 1050301, '채우기 전에 친해지는 목줄', 1, '목줄을 채우기 전에 목줄의 모양과 버클 소리부터 편안하게 느끼도록 도와주세요. 목줄과 작은 간식을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030102, 1050301, '작은 관심에도 주는 보상', 2, '목줄 주변과 안쪽에 간식을 놓아 스스로 가까이 가게 해 주세요. 목줄을 쳐다보거나 살짝 건드리는 작은 관심도 바로 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030103, 1050301, '손 위에 올린 목줄', 3, '바닥에 놓인 목줄이 익숙해지면 손 위에 목줄을 올리고 안쪽과 가운데에 먹이를 놓아 먹게 해 주세요. 손과 목줄을 함께 편안하게 느끼는 단계예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030104, 1050301, '버클 소리 뒤에 오는 간식', 4, '버클을 채우지 않은 채 소리만 들려주고 바로 간식을 주세요. 익숙해지면 머리 뒤쪽처럼 보이지 않는 곳에서도 같은 연습을 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030105, 1050301, '소리에 피하지 않으면 다음 단계', 5, '버클 소리를 들어도 피하거나 놀라지 않으면 다음 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030201, 1050302, '도둑과 경찰 놀이가 되지 않게', 1, '줄을 매려 할 때마다 도망 다니는 기억을 만들지 마세요. 줄을 매다 도망가는 경험은 오래 남으니 처음에는 다른 사람의 도움을 받아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030202, 1050302, '채우는 사람과 주는 사람', 2, '강아지가 좋아하는 사람이 목줄을 채우고 다른 사람이 간식을 주세요. 처음에는 목줄을 넉넉하게 조절해 부담을 줄여 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030203, 1050302, '덮치듯 다가가지 않는 자세', 3, '위에서 덮치듯 다가가지 말고 턱을 부드럽게 받쳐 주세요. 버클 소리가 크게 나지 않도록 천천히 채우며 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030204, 1050302, '도망가지 않고 채우게 두면 성공', 4, '도망가지 않고 편안하게 목줄을 채우도록 기다려 주면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030301, 1050303, '처음 경험하는 가슴줄', 1, '등에 T자로 올라가는 가슴줄은 생전 처음 경험하는 경우가 많으니 더 천천히 진행해 주세요. 줄 길이를 최대한 늘리고 특히 양쪽 목 부분을 넉넉하게 해서 채워 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030302, 1050303, '보고 도망갈 때의 대처', 2, '보고 도망가면 일단 가슴줄을 내려놓고 강아지를 불러 주세요. 목줄을 잡아 더 멀어지지 않게 한 채 간식으로 달래며 천천히 기다리고, 보호자가 흔들리지 않는 것이 중요해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030303, 1050303, '간질이며 하나씩 빼 주는 귀', 3, '간질간질하게 만져 주며 천천히 진행해 주세요. 귀도 한쪽씩 천천히 빼 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030304, 1050303, '잡혔다고 느끼면 어려워지는 학습', 4, '몸을 붙잡혔다고 느끼면 학습하기 어려워지는 강아지도 있어요. 괜찮다고 차분히 말하며 한 단계씩 진행해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105030305, 1050303, '떨어도 지나가는 첫 경험', 5, '처음에 몸을 떨어도 보호자가 침착하면 차츰 적응할 수 있어요. 보호자의 불안이 전해지지 않도록 평소처럼 차분하게 행동해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105040101, 1050401, '사람이 먼저 다가가지 않는 인사', 1, '사람이 먼저 다가가지 않고 강아지가 스스로 오게 하는 것이 인사의 기본이에요. 온 뒤에도 급히 만지지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105040102, 1050401, '가만히 서서 하는 기다림', 2, '사람은 가만히 있고 강아지가 냄새를 맡으며 스스로 다가오게 두세요. 냄새 맡는 중에 아는 척하거나 갑자기 만지면 놀라요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105040103, 1050401, '만지는 것은 인사가 아니다', 3, '만지는 것을 좋아하는 강아지도 낯선 사람의 손길은 싫어할 수 있어요. 간식을 두고 익숙해질 시간을 주고, 다가온 뒤에도 접촉은 천천히 늘려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105040104, 1050401, '목소리가 울리지 않는 조용한 곳', 4, '목소리가 울리는 공간은 강아지를 더 불안하게 할 수 있어요. 조용한 곳에서 시작하고 상황이 끝난 뒤에도 과하게 반응하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105040105, 1050401, '스스로 다가와 머물면 성공', 5, '낯선 사람에게 스스로 다가가 냄새를 맡고 곁에 머물 수 있으면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050101, 1050501, '훅 다가가지 않는 첫 만남', 1, '무서워하는 강아지에게 밝은 목소리로 훅 다가가지 마세요. 반가움을 크게 표현할수록 더 물러설 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050102, 1050501, '주고 기다렸다 다시 시작하는 리듬', 2, '가만히 있다가 좋아하는 것을 한두 개 주고, 기다렸다가 다시 시작해 주세요. 이런 리듬을 편안해하는 강아지가 많아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050103, 1050501, '권하는 것 자체가 되는 압박', 3, '간식을 안 먹는다고 먹어 보라고 권하는 것 자체가 압박이 돼요. 그냥 가만히 있고 간식은 바닥에 떨어뜨려 슬쩍 다가오게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050104, 1050501, '줄여야 할 말과 시선', 4, '말을 많이 하지 마세요. 쳐다보는 것만으로도 압박이 될 수 있고, 앉았다 일어서기만 해도 다른 사람처럼 느끼니 어제 친해졌어도 오늘 다시 알아갈 시간을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050105, 1050501, '도망만 안 가도 진전', 5, '도망만 가지 않아도 충분한 진전이에요. 식욕이 있으면 회복이 빠르니, 잘 안 풀리는 날은 강요하지 말고 다음을 기약해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050201, 1050502, '4개월부터 시작되는 사람 구별', 1, '생후 4개월 무렵부터 강아지는 편안한 사람과 불편한 사람을 구별하기 시작해요. 의심하는 모습을 문제로 보지 말고 충분히 관찰할 시간을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050202, 1050502, '두고 멀리 빠지는 간식', 2, '권하지 말고 간식을 강아지 앞이나 가져온 장난감 위에 그냥 두고 멀리 빠져 주세요. 권하지 않고 두면 스스로 용기를 내서 먹어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050203, 1050502, '먹어도 하지 않는 칭찬', 3, '먹어도 칭찬하지 말고 가만히 두세요. 의심해서 오지 않으면 더 멀리 빠져 부담을 줄이고 스스로 올 때까지 기다려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050204, 1050502, '스스로 다가오면 성공', 4, '사람을 살펴본 뒤 스스로 편안한 사람에게 다가갈 수 있으면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050301, 1050503, '어릴 때 소극적으로 보이는 견종', 1, '어릴 때 소극적으로 보이는 견종이 있어요. 주고받기가 잘 안 되는 것처럼 보여도 이갈이가 끝나는 7개월에서 8개월쯤 달라질 수 있으니 조급해하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050302, 1050503, '주머니에 늘 넣어 두는 먹이', 2, '그때까지 주머니에 먹이를 넣고 다니며 계속 조금씩 먹여 주세요. 보호자 곁이 좋은 곳이라는 경험을 꾸준히 쌓아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050303, 1050503, '명령보다 앞서는 동작', 3, '말로 명령하기보다 보호자의 움직임으로 안내해 주세요. 다리 사이로 오게 하거나 간식을 천천히 내려 자연스럽게 엎드리게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050304, 1050503, '작은 교류에도 주는 보상', 4, '점프하거나 손을 대는 작은 교류가 나오면 바로 보상해 주세요. 작은 반응부터 쌓는 것이 이 단계의 목표예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050401, 1050504, '점프는 성격 좋은 강아지의 표현', 1, '낯선 사람에게 점프하고 꼬리를 치는 것은 성격 좋은 강아지의 표현이에요. 무릎으로 밀칠 필요가 전혀 없어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050402, 1050504, '살짝 움직여 맡게 하는 냄새', 2, '세게 밀지 말고 몸을 살짝 움직여 냄새를 맡게 해 주세요. 멈춰서 생각하는 순간 "옳지"라고 말하고 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050403, 1050504, '잘게 자르지 않은 스틱형 간식', 3, '잘게 자른 간식보다 스틱형 간식을 손에 잡고 하나씩 물어뜯게 해 주세요. 먹는 시간이 길어지며 흥분이 가라앉아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105050404, 1050504, '간식을 흘리지 않는 손', 4, '간식을 바닥에 자주 떨어뜨리면 냄새를 찾는 습관이 생길 수 있어요. 손에서 안정적으로 먹을 수 있도록 천천히 건네주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105060101, 1050601, '엉덩이 냄새를 맡는 개들의 인사', 1, '개끼리의 인사는 뒤쪽 냄새를 맡는 거예요. 앞에서 들이밀거나 올라타는 것은 인사가 아니라 지배 행동이고, 만났다고 꼭 인사해야 하는 것도 아니에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105060102, 1050601, '시각과 후각, 동행의 3단계', 2, '줄을 풀지 말고 거리를 둔 채 눈으로만 서로를 보게 해 주세요. 그다음 자리를 바꿔 상대가 있던 자리의 냄새를 맡게 하고, 마지막으로 같은 방향으로 천천히 걸으며 산책해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105060103, 1050601, '하루 세 번의 짧은 산책', 3, '산책은 하루 세 번이 좋고, 시간이 없으면 5분씩 소변만 보고 들어와도 괜찮아요. 횟수를 지키는 것이 길이보다 중요해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105060104, 1050601, '3단계 인사가 되면 성공', 4, '상대 강아지를 눈으로 보고, 냄새를 맡고, 나란히 걷는 세 단계를 차분하게 진행하면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105060201, 1050602, '보호자끼리 먼저 하는 인사', 1, '멀리 떨어져 인사해도 되는지 먼저 물어봐 주세요. 허락받았다면 강아지를 앞세우지 말고 보호자끼리 자연스럽게 다가가 인사해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105060202, 1050602, '개들의 자유인 인사', 2, '인사할지 말지는 강아지들의 자유예요. 짧게 두고 불편해서 빠지면 쫓아가지 말고, 줄이 꼬이지 않게 주의해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105060203, 1050602, '앉아 버리는 것은 거부 신호', 3, '상대 강아지가 앉아서 멈춘다면 인사를 원하지 않는다는 신호일 수 있어요. 거리를 벌리고, 올라타려는 강아지와는 인사하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105060204, 1050602, '헤어질 때 사이를 막는 몸', 4, '인사를 마칠 때는 보호자가 두 강아지 사이를 몸으로 막으며 자연스럽게 이동해 주세요. 마주 본 채 그냥 돌아서면 달려들 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105060205, 1050602, '거부 신호를 읽고 물러나면 성공', 5, '상대 강아지의 거부 신호를 읽고 자연스럽게 물러날 수 있으면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070101, 1050701, '활동적인 견종에게 흔한 반응', 1, '인사하고 싶어 짖고 낑낑대는 것은 활동적인 견종에게 흔한 일이에요. 큰 문제가 아니니 에너지를 먼저 빼 주는 쪽으로 접근해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070102, 1050701, '입장 전에 빼는 에너지', 2, '운동장에 바로 들어가지 말고 줄을 맨 채 주변을 산책하며 에너지를 빼 주세요. 뛰는 시간을 충분히 가진 뒤에 입장해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070103, 1050701, '차분해진 뒤에 하는 만남', 3, '에너지가 빠지면 줄을 맨 채 입장해 왔다 갔다 하며 냄새를 맡게 해 주세요. 차분해지면 조금씩 다른 강아지와 만나게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070104, 1050701, '노는 친구가 되어 주는 보호자', 4, '보호자가 함께 노는 친구가 되어 주세요. 돗자리를 깔고 구경만 하면 보호자에 대한 집중이 사라지고, 끝난 뒤에도 줄을 매고 함께 걸어 나와 조금 걷다가 헤어져 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070105, 1050701, '보호자와 노는 경험이 만드는 여유', 5, '밖에 나가면 보호자와 논다는 경험이 깔려 있어야 조금만 기다리라는 말도 통해요. 함께 노는 시간을 꾸준히 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070201, 1050702, '섞지 않아야 할 활동적인 개', 1, '다른 개를 무서워하는 강아지를 활동적인 개와 놀게 하면 충격을 받을 수 있어요. 활동적인 개는 함께 두지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070202, 1050702, '비슷한 성향의 또래', 2, '소극적이고 조용하며 체격이 비슷한 또래끼리 만나 냄새 맡기와 가벼운 장난부터 시작해 주세요. 실내 애견카페도 비슷한 성향의 강아지들만 있다면 괜찮아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070203, 1050702, '피하기만 하면 생기는 혼란', 3, '만나지 않고 피하기만 하면 두세 살 무렵 정체성에 혼란이 올 수 있어요. 안전한 상대와 어울리는 연습을 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070204, 1050702, '어느 순간 열리는 문', 4, '반복하다 보면 어느 순간 문이 열리듯 다른 강아지들과 어울리기 시작하기도 해요. 조급해하지 말고 기회를 계속 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070301, 1050703, '공격이 아니라 묻는 짖음', 1, '소극적인 강아지의 짖음은 공격이 아니라 어떻게 해야 하는지 묻는 신호예요. 보호자는 담담하게 반응해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070302, 1050703, '반기는 사람보다 의연한 사람', 2, '소극적인 강아지는 과하게 반기는 사람보다 차분한 사람을 편하게 느낄 수 있어요. 옆에서 움직일 때도 반대쪽으로 천천히 일어나 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070303, 1050703, '보호자가 안내하는 만남', 3, '낯선 사람이 보호자와 먼저 인사하고 보호자가 앞장서 걸으면 좋은 사람으로 인식해요. 만지지 말고 주먹 냄새를 맡으며 스스로 두려움을 떨쳐내게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070304, 1050703, '자신감을 쌓는 냄새 활동', 4, '냄새 찾기처럼 자신감을 키우는 활동을 계속해 주세요. 문제가 생겨도 해결할 수 있다는 경험이 쌓이면 작은 일은 금방 넘겨요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070401, 1050704, '각각 놀아 주며 맞추는 에너지', 1, '처음부터 두 강아지를 함께 놀게 하지 말고 보호자가 각각 따로 놀아 주세요. 두 강아지의 에너지 수준이 비슷해질 때까지 충분히 시간을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070402, 1050704, '미는 강아지와 벌리는 간격', 2, '한 강아지가 다른 강아지를 계속 밀면 부드럽게 거리를 벌려 주세요. 서로 편안하게 머물 수 있는 간격을 유지해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070403, 1050704, '데면데면한 룸메이트 같은 사이', 3, '항상 붙어 노는 관계보다 서로 편안하게 쉬는 룸메이트 같은 관계가 더 건강할 수 있어요. 가까이 있으라고 강요하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070404, 1050704, '켄넬을 번갈아 쓰는 휴식', 4, '두 강아지의 에너지 수준이 맞지 않으면 켄넬을 번갈아 사용해 주세요. 각자 방해받지 않고 쉬는 시간을 보장해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070405, 1050704, '6개월에서 7개월의 변화', 5, '생후 6개월에서 7개월쯤이면 서로의 거리를 스스로 찾아가요. 그때까지는 보호자가 간격을 조절해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070501, 1050705, '한 마리씩 따로 쓰는 잠자리', 1, '처음에는 두 강아지를 한 마리씩 따로 재워 주세요. 혼자 쉬어도 안전하다는 경험을 각각 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070502, 1050705, '번갈아 나가는 산책', 2, '산책도 한 마리씩 번갈아 데리고 나가 충분히 놀아 주세요. 집에 남은 강아지는 보호자와 떨어져 쉬는 경험을 하게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070503, 1050705, '두 사람이 다른 길로 걷는 외출', 3, '두 강아지가 함께 나가야 한다면 보호자 두 명이 서로 다른 경로로 걸어 주세요. 각자 보호자에게 집중할 수 있도록 도와주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070504, 1050705, '요일을 나누는 유치원', 4, '유치원에 보낼 때도 요일을 나눠 각자 경험하게 해 주세요. 두 강아지가 항상 함께 움직이는 습관을 만들지 않는 것이 좋아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070601, 1050706, '압박하는 순간의 개입', 1, '첫째가 둘째를 압박하면 보호자가 사이를 막아 주세요. 그 순간 둘째에게 간식을 주어 보호자 곁이 안전하다는 것을 알려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070602, 1050706, '보호자 앞에서는 안 된다는 규칙', 2, '첫째에게는 보호자 앞에서 동생을 압박할 수 없다는 규칙을 일관되게 알려 주세요. 큰 소리로 혼내기보다 몸으로 차분히 막아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070603, 1050706, '하루 한두 번 짧게 하는 양손 급여', 3, '양손으로 두 강아지에게 번갈아 간식을 주는 연습을 하루 한두 번 짧게 해 주세요. 먹이를 지키려는 행동이 있다면 이 연습은 하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(105070604, 1050706, '압도적으로 늘리는 바깥 시간', 4, '집 안에서 경쟁하지 않도록 바깥에서 각자 놀고 탐색하는 시간을 충분히 늘려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010101, 1060101, '외출 물품 목록 적기', 1, '내가 나갈 때 챙기는 물건을 전부 적어 보세요. 가방, 외투, 차 키, 지갑, 화장품처럼 사소한 것까지 빠짐없이 적어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010102, 1060101, '물건을 2시간 전에 현관에 두기', 2, '외출 최소 2시간 전에 그 물건들을 모두 꺼내 현관 근처에 미리 두세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010103, 1060101, '준비 중에는 반응하지 않기', 3, '준비하는 동안 강아지가 서성이거나 낑낑대도 반응하지 말고 하던 일을 계속하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010104, 1060101, '준비 동작 없이 바로 나가기', 4, '실제로 나갈 때는 미리 둔 물건만 집어 들고 바로 나가세요. 준비 동작 없이 나가는 것이 핵심이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010201, 1060102, '나가기 직전 인사하지 않기', 1, '나가기 직전에 강아지에게 하이톤으로 인사하거나 안아 주지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010202, 1060102, '눈 맞춤 없이 평소 걸음으로 현관까지', 2, '눈을 맞추거나 쓰다듬지 말고, 평소 걸음으로 현관까지 이동하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010203, 1060102, '문은 소리 없이 조용히 여닫기', 3, '문은 소리가 나지 않게 조용히 여닫으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010204, 1060102, '현관 앞에서 머뭇거리지 않기', 4, '현관 앞에서 머뭇거리지 마세요. ''외출 준비 신호 지우기'' 레슨대로 준비가 끝나 있으면 동선이 짧아져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010205, 1060102, '돌아왔을 때 보지도 만지지도 않기', 5, '문을 열고 들어왔을 때 강아지가 뛰어오르며 반겨도 보지 않고, 만지지 않고, 말을 걸지 않으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010206, 1060102, '내 할 일 먼저 하기', 6, '겉옷을 벗고 짐을 정리하는 등 내 할 일을 먼저 하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010207, 1060102, '네 발이 바닥에 붙을 때까지 기다리기', 7, '강아지의 네 발이 바닥에 붙고 흥분이 가라앉을 때까지 기다리세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010208, 1060102, '차분해진 뒤에 인사하기', 8, '차분해진 것을 확인한 뒤, 그때 낮고 부드러운 목소리로 인사하고 쓰다듬어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010301, 1060103, '외출 1시간 전 산책 시작하기', 1, '외출 예정 시각을 기준으로 1시간 전에 산책을 시작하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010302, 1060103, '냄새 맡으며 여유 있게 걷기', 2, '20~30분 동안 강아지가 냄새를 충분히 맡을 수 있게 여유 있게 걸으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010303, 1060103, '귀가 후 숨 고르고 조용히 나가기', 3, '산책에서 돌아온 뒤 물을 마시고 숨을 고를 시간을 준 다음, ''출입 루틴 만들기'' 레슨의 규칙대로 조용히 나가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010304, 1060103, '백색소음 일상화하기', 4, '빗소리, 팬 소리 같은 백색소음을 보호자가 집에 함께 있을 때부터 틀어서 일상적인 소리로 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010305, 1060103, '외출할 때도 같은 소리와 볼륨으로', 5, '외출할 때도 같은 소리, 같은 볼륨으로 틀어 두세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010306, 1060103, '볼륨은 대화가 방해되지 않는 수준으로', 6, '볼륨은 사람의 대화가 방해되지 않는 수준이면 충분해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010401, 1060104, '안정 페로몬 보조 수단 이해하기', 1, '아답틸은 어미 개가 분비하는 안정 페로몬을 모방한 제품으로, 불안을 낮추는 보조 수단이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010402, 1060104, '쉬는 공간에 디퓨저 꽂아 두기', 2, '디퓨저형 제품이라면 강아지가 주로 쉬는 공간에 꽂아 두세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010403, 1060104, '교육 대체 수단으로 쓰지 않기', 3, '페로몬 제품은 보조 수단일 뿐이에요. 이것만으로 교육을 대체하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010404, 1060104, '혼자 버틸 수 있는 시간 기준 삼기', 4, '현재 아이가 혼자 버틸 수 있는 시간을 기준으로 삼으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010405, 1060104, '기준을 넘는 외출은 데이케어·펫시터로', 5, '그 시간을 넘는 외출, 예를 들어 출근이나 장시간 약속은 훈련이 아니라 관리로 해결해요. 유치원, 데이케어, 펫시터를 예약하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010406, 1060104, '진도가 리셋되는 것 막기', 6, '이렇게 해야 훈련 수준을 넘는 외출로 진도가 리셋되는 것을 막을 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010407, 1060104, '외출 전용 최고의 간식과 장난감 정하기', 7, '평소에는 절대 주지 않는 최고 등급의 간식과 전용 장난감을 하나 정하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010408, 1060104, '외출할 때만 제공하기', 8, '이 조합은 오직 보호자가 외출할 때만 제공하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106010409, 1060104, '돌아오면 남아 있어도 회수하기', 9, '돌아오면 간식이 남아 있어도 회수하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020101, 1060201, '방석을 거실 바닥에 내려놓기', 1, '방석을 거실 바닥에 내려놓으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020102, 1060201, '스스로 다가올 때까지 기다리기', 2, '부르지 말고 기다리세요. 강아지가 스스로 다가와 방석 냄새를 맡을 때까지 기다려요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020103, 1060201, '냄새를 맡으면 방석 위에 간식 올리기', 3, '강아지가 방석 냄새를 맡으면 방석 위에 간식 1알을 올려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020104, 1060201, '먹고 쳐다보면 1알 더 올려 주기', 4, '강아지가 방석에 올라가 간식을 먹고 보호자를 쳐다보면, 방석 위에 1알을 더 올려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020105, 1060201, '크게 한 바퀴 돌리고 다시 간식 올리기', 5, '간식을 든 손을 강아지 코앞에 대고 천천히 움직여, 강아지가 따라오며 크게 한 바퀴 돌게 하세요. 그리고 다시 방석 위에 간식을 올려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020106, 1060201, '한 세션에 5~10회 반복하기', 6, '간식 올리기부터 한 바퀴 돌기까지의 과정을 한 세션에 5~10회 반복하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020201, 1060202, '한 끼 사료를 손닿는 곳에 두기', 1, '한 끼 분량의 사료를 그릇에 주지 말고 손이 닿는 곳에 두세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020202, 1060202, '방석 위 강아지에게 한 알씩 던져 주기', 2, '소파에 앉아 TV를 보는 등 평소처럼 지내면서, 방석 위에 있는 강아지에게 사료를 한 알씩 던져 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020203, 1060202, '파고들면 주지 않고 방석으로 돌아가면 주기', 3, '강아지가 무릎 사이로 파고들면 주지 마세요. 방석으로 돌아가면 그때 던져 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020204, 1060202, '던지는 간격 조금씩 늘리기', 4, '익숙해지면 던지는 간격을 조금씩 늘리세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020205, 1060202, '방석 기다리기가 익숙해진 뒤 시작하기', 5, '방석에서 기다리기가 익숙해진 상태에서 허락 연습을 시작하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020206, 1060202, '기다리고 있을 때 신호와 함께 허락하기', 6, '방석에서 예쁘게 기다리고 있을 때, ''올라와'' 같은 신호와 함께 무릎이나 소파에 올라오는 것을 허락해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020207, 1060202, '허락은 자주 해도 되지만 순서가 핵심', 7, '허락은 자주 해 줘도 괜찮아요. 핵심은 허락받고 올라온다는 순서예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020208, 1060202, '허락 없이 올라오면 내려 주고 다시 시작', 8, '허락 없이 올라오면 조용히 내려 주고, 방석으로 유도한 뒤 다시 시작하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020301, 1060203, '턱이 있는 방석으로 바꾸기', 1, '턱이 없는 방석을 잘 쓰게 됐다면, 이제 턱이 있는 방석으로 바꿔 보세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020302, 1060203, '도와주지 말고 재촉하지 말고 기다리기', 2, '별것 아닌데도 강아지가 어렵게, 낑낑대며 올라갈 수 있어요. 도와주지 말고, 재촉하지 말고 기다리세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106020303, 1060203, '스스로 성공하면 크게 칭찬하기', 3, '강아지가 스스로 올라가는 데 성공하면 크게 칭찬하고 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030101, 1060301, '정면 한 걸음 앞에 서기', 1, '강아지 정면 한 걸음 앞에 서세요. 이 실행 틀은 안정화 교육의 모든 레슨에서 똑같이 반복돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030102, 1060301, '''앉아''라고 말하기', 2, '''앉아''라고 말하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030103, 1060301, '''기다려''와 함께 손바닥 보여 주기', 3, '강아지가 앉으면 ''기다려''라고 말하며 손바닥을 보여 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030104, 1060301, '그 상태에서 과제 수행하기', 4, '그 상태를 유지한 채 각 카드의 과제를 수행하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030105, 1060301, '유지했다면 칭찬하고 간식 주기', 5, '강아지가 자세를 유지했다면 ''옳지''라고 말하거나 클리커를 누르고, 0.5초 뒤에 무릎을 굽혀 간식을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030106, 1060301, '실패하면 담담하게 처음부터', 6, '강아지가 일어나거나 따라왔다면 간식 없이 담담하게 첫 카드부터 다시 시작하세요. 2번 연속 실패하면 이전 레슨으로 내려가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030201, 1060302, '2초 세고 보상하기', 1, '''기다려''라고 말한 뒤 속으로 2초를 세고 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030202, 1060302, '5초 세고 보상하기', 2, '같은 방법으로 5초를 세고 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030203, 1060302, '10초 세고 보상하기', 3, '같은 방법으로 10초를 세고 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030204, 1060302, '뒤로 물러나는 척만 하기', 4, '이동할 때는 강아지를 바라본 채 뒷걸음으로 움직이세요. 처음에는 물러나는 척만 해요. 한 발에 체중만 옮겼다가 바로 제자리로 돌아온 뒤 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030205, 1060302, '뒤로 한 걸음 물러났다 돌아오기', 5, '뒤로 한 걸음 물러났다가 돌아온 뒤 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030206, 1060302, '뒤로 두 걸음 물러났다 돌아오기', 6, '뒤로 두 걸음 물러났다가 돌아온 뒤 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030207, 1060302, '오른쪽으로 물러나는 척만 하기', 7, '오른쪽으로 한 걸음 물러나는 척만 하고 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030208, 1060302, '왼쪽으로 물러나는 척만 하기', 8, '왼쪽으로 한 걸음 물러나는 척만 하고 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030209, 1060302, '좌우로 실제 한 걸음씩 이동하기', 9, '좌우로 실제로 한 걸음씩 이동했다가 돌아온 뒤 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030301, 1060303, '박수 살짝 한 번 치기', 1, '''기다려'' 상태에서 박수를 살짝 한 번 치고, 자세를 유지하면 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030302, 1060303, '박수 조금 세게 치기', 2, '박수를 조금 세게 치고, 자세를 유지하면 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030303, 1060303, '큰 소리로 20까지 세기', 3, '''기다려''라고 말한 뒤, 큰 소리로 하나부터 스물까지 세세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030304, 1060303, '일어난 숫자로 한계점 기억하기', 4, '중간에 강아지가 일어났다면 그 숫자를 기억해 두세요. 그 지점이 현재 우리 아이의 한계점이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030305, 1060303, '한계점보다 낮은 지점에서 성공시키기', 5, '다음 시도에서는 한계점보다 2~3 낮은 숫자에서 멈추고 보상하세요. 성공 경험을 만든 뒤 조금씩 늘려 가요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030306, 1060303, '강아지 주위 천천히 한 바퀴 돌기', 6, '''기다려'' 상태의 강아지 주위를 천천히 한 바퀴 도세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030307, 1060303, '완주 못 해도 중간 보상 가능', 7, '한 바퀴 돌기는 난이도가 높은 과제예요. 완주하지 못해도 어느 정도 기다렸다면 중간에 보상을 줘도 괜찮아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030401, 1060304, '손잡이를 한 번 만지고 돌아오기', 1, '몸의 방향을 강아지 쪽으로 유지한 채 뒷걸음으로 이동하세요. ''기다려''라고 말한 뒤 방문 손잡이를 한 번 만지고 돌아와 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030402, 1060304, '문을 열고 5초 서 있다가 돌아오기', 2, '문을 열고 5초 동안 서 있다가 돌아와 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030403, 1060304, '문을 연 채로 방 안에 5초 들어가기', 3, '문을 닫지 말고 연 채로 방 안에 5초 동안 들어갔다가 돌아와 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106030404, 1060304, '등을 돌리고 방에 들어갔다 돌아오기', 4, '이번에는 등을 돌리고 방에 들어갔다가 돌아와 보상하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040101, 1060401, '간식 주고 손바닥 냄새 맡게 하기', 1, '방석 위에 있는 강아지에게 간식을 1개 주고, 손바닥 냄새를 충분히 맡게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040102, 1060401, '손바닥 보이며 차분하게 ''다녀올게''', 2, '손바닥을 강아지에게 보여 주며, 급하지 않게 차분한 목소리로 ''다녀올게''라고 말하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040103, 1060401, '시야 안의 다른 공간에서 볼일 보기', 3, '말한 뒤 급하게 도망치듯 가지 말고, 자연스럽고 신속하게 강아지 시야 안의 다른 공간으로 가서 물을 마시는 등 볼일을 보세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040104, 1060401, '돌아와 다시 손바닥 냄새 맡게 하기', 4, '자연스럽게 돌아와서 다시 손바닥 냄새를 맡게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040105, 1060401, '방석에서 기다렸다면 간식 주기', 5, '강아지가 방석에서 예쁘게 기다렸다면 간식을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040106, 1060401, '하루 여러 번 놀이처럼 반복하기', 6, '이 루틴을 하루에 여러 번, 놀이처럼 반복하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040201, 1060402, '콩토이에 끈 통과시켜 단단히 묶기', 1, '콩토이에 끈을 통과시켜 단단히 묶으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040202, 1060402, '최고 등급 간식 채우기', 2, '안에 최고 등급의 간식을 채우세요. 간식을 넣고 얼리면 먹는 시간이 길어져 더 오래가요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040203, 1060402, '첫 일주일은 교육 없이 그냥 주기만', 3, '첫 일주일 동안은 교육하지 마세요. 보호자가 집에 있을 때 하루에 한 번 간식을 채워 그냥 주기만 하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040204, 1060402, '다 먹기 전에 끈으로 회수하기', 4, '강아지가 다 먹기 전에 끈을 이용해 회수하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040301, 1060403, '간식 채운 콩토이 내려놓기', 1, '간식을 채운 콩토이를 바닥에 내려놓으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040302, 1060403, '몰두하면 조용히 문 쪽으로 걸어가기', 2, '강아지가 콩토이에 몰두하면 조용히 문 쪽으로 걸어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040303, 1060403, '따라오는지 확인하기', 3, '여기서 갈림길이에요. 강아지가 따라온다면 아직 준비가 안 된 것이니, 일주일 더 ''콩토이 가치 올리기'' 레슨의 그냥 주기로 돌아가거나 안에 넣는 간식을 더 맛있는 것으로 바꿔 주세요. 따라오지 않는다면 처음에는 문고리만 한 번 만지고 돌아오세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040304, 1060403, '돌아와서 콩토이 회수하기', 4, '돌아와서 끈을 이용해 콩토이를 회수하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040305, 1060403, '문을 열어 봤다가 돌아와 다시 회수하기', 5, '다시 콩토이를 내려놓고, 이번에는 문까지 가서 문을 열어 봤다가 돌아와 다시 회수하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040306, 1060403, '초 단위로 차근차근 늘리기', 6, '세션을 거듭하며 조금씩 늘리세요. 문 열고 1초 나갔다 오기, 5초 나갔다 오기, 문 닫고 5초 있기처럼 시간을 차근차근 늘려 가요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106040307, 1060403, '매번 돌아오면 회수하기', 7, '매번 돌아오면 콩토이를 회수하세요. 강아지가 다 먹기 전에 교육을 끝내야 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050101, 1060501, '켄넬 앞에 앉아 담담히 지켜보기', 1, '켄넬 앞에 그냥 앉으세요. 말을 걸지 말고, ''너 지금 흥분했네'' 하는 담담한 눈으로 지켜보기만 하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050102, 1060501, '손잡이에 손만 대고 멈추기', 2, '켄넬 문 손잡이에 손만 대고 멈추세요. 강아지는 문이 열릴 거라 예측하고 잠잠해져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050103, 1060501, '열지 않고 손 떼고 크게 한숨 쉬기', 3, '문을 열지 않고 손을 떼세요. 그리고 크게 한숨을 쉬세요. 너의 불안에 공감하지 않는다는 신호예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050104, 1060501, '크게 불안해해도 개입하지 않기', 4, '강아지가 헐떡이며 크게 불안해해도 개입하지 말고 그대로 지켜보세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050105, 1060501, '낑낑대며 울어도 반응하지 않기', 5, '낑낑대며 울어도 반응하지 마세요. 담담한 태도를 유지하며 상태를 직면하되, 대응하지 않아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050106, 1060501, '조금만 열고 나오려 하면 과감하게 닫기', 6, '문을 10cm만 여세요. 강아지가 나오려고 코를 내밀면 과감하게 닫으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050107, 1060501, '조금 더 열고 또 나오려 하면 단호하게 닫기', 7, '다시 조금 더 열고 기다리세요. 또 나오려고 하면 단호하게 밀어 넣고 닫으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050108, 1060501, '문 연 채 일어나 켄넬에 가까이 서기', 8, '이번에는 문을 연 채로 그대로 일어나서 켄넬에 가까이 붙어 서세요. 가만히 서 있는 것 자체가 강아지에게 커다란 압박이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050109, 1060501, '진정 기미가 보이면 예뻐해 주기', 9, '강아지가 진정될 기미를 보이면 앞으로 가서 ''이리 와'' 하고 예뻐해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050110, 1060501, '예뻐해 주는 그 순간에 켄넬 문 잠그기', 10, '예뻐해 주는 바로 그 순간에 켄넬 문을 잠그세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050201, 1060502, '켄넬 문 잠가 두기', 1, '켄넬 문을 잠가 두세요. 강아지는 밖에 있는 상태예요. 불안할 때 켄넬로 도피해 숨는 것을 막는 조치예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050202, 1060502, '무심하게 지나쳐 현관 근처로 가기', 2, '강아지를 무심하게 지나쳐 부엌처럼 현관과 가까운 곳으로 가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050203, 1060502, '현관과 강아지 사이로 들어가기', 3, '현관과 강아지 사이로 들어가세요. 조금 천천히 해도 괜찮아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050204, 1060502, '손바닥 보이며 크게 한숨 쉬기', 4, '거리를 유지한 채 손바닥을 보이며 크게 한숨을 쉬세요. 다가오지 말라는 거절 의사예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050205, 1060502, '문 손잡이에 손 대며 손바닥 보이기', 5, '현관에 들어서서 문 손잡이에 손을 대며, 강아지에게 손바닥을 보이세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050206, 1060502, '손잡이에서 손만 떼며 텀 만들기', 6, '손잡이에서 손만 떼세요. 이 잠깐의 멈춤이 ''텀''이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050207, 1060502, '가까이 오면 오른발로 슬며시 막기', 7, '강아지가 가까이 오면 손바닥을 보이며 다가가, 오른발로 슬며시 막으세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050208, 1060502, '사이로 들어오려 하면 막으며 ''안 돼''', 8, '담담한 태도로 가만히 기다리고, 강아지가 보호자와 현관문 사이로 들어오려 하면 발로 막으며 ''안 돼''라고 하세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050301, 1060503, '문을 열고 밖으로 나가기', 1, '그대로 문을 열고 밖으로 나가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050302, 1060503, '들어와서 가만히 선 뒤 크게 한숨 쉬기', 2, '들어와서 현관 앞에 가만히 선 뒤 크게 한숨을 쉬세요. 강아지가 스스로 뒤돌아 물러나면 신호가 통한 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050303, 1060503, '담담하게 말 걸고 손 냄새만 맡게 하기', 3, '''뭐 하고 있었어?'' 하고 담담하게 말을 걸고, 앉되 만지지는 말고 손을 내밀어 냄새를 충분히 맡게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050304, 1060503, '모든 외출 신호에 동작·멈춤·텀 반복하기', 4, '이후 일상의 모든 외출 신호에 같은 순서를 끼워 넣으세요. 가방을 들 때, 옷을 입을 때, 도어락을 누를 때마다 동작하고, 멈추고, 텀을 두는 것을 반복해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050401, 1060504, '줄을 정리하는 척 만지작거리기', 1, '목줄을 가져와 바로 채우지 말고, 줄을 정리하는 척 만지작거리세요. 강아지에게 준비할 시간을 주는 시간차 훈련의 응용이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050402, 1060504, '목줄 착용시키기', 2, '목줄을 착용시키세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050403, 1060504, '목줄을 침대 다리에 고정하기', 3, '목줄을 침대 다리에 고정하세요. 목줄로 보호자와 거리를 두면서도, 보호자가 근처에 있다는 것을 알려 주는 장치예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050404, 1060504, '현관에서 손바닥 보이며 ''다녀올게''', 4, '시간차 훈련의 루틴 그대로 차분히 현관으로 가서, 손바닥을 보이며 ''다녀올게''라고 하세요. 이때 강아지가 낑낑대며 다가오려다 목줄을 물어뜯더라도 실패가 아니에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050405, 1060504, '몇 걸음 다가가 서기', 5, '단호하게 몇 걸음 강아지 쪽으로 다가가 서세요. 거리는 유지해요. 압박을 주는 동작이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050406, 1060504, '떨림과 빠른 호흡에 개입하지 않기', 6, '강아지가 몸을 떨고 호흡이 빨라질 수 있어요. 개입하지 말고 그대로 두세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050407, 1060504, '스스로 흥분을 참는 법 배우게 두기', 7, '가만히 두면 강아지가 스스로 흥분을 참는 법을 배우게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050408, 1060504, '목줄을 물어뜯으면 들어서 제지하기', 8, '다시 목줄을 물어뜯으려 하면 다가가서 목줄을 번쩍 들어 압박하고, 놓은 뒤 바로 등을 돌려 제자리로 돌아가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050409, 1060504, '스스로 엎드리면 이 라운드 성공', 9, '강아지가 몸을 벌벌 떨거나 스스로 엎드리면 이 라운드는 성공이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050501, 1060505, '현관이 보이는 다른 위치에 다시 고정하기', 1, '줄을 풀어 부엌 수도꼭지처럼 현관이 보이는 다른 위치에 다시 고정하세요. 다양한 장소에 적응하도록 위치를 옮겨 가며 반복해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050502, 1060505, '신발까지 신고 손바닥 보이며 기다리기', 2, '이번에는 현관까지 가서 신발까지 신고, 손바닥을 보이며 기다리세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050503, 1060505, '엎드릴 때까지 시간 들여 기다리기', 3, '시간이 오래 걸려요. 휴대폰을 보거나 책을 읽으면서 강아지가 엎드릴 때까지 기다리세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050504, 1060505, '힘들어하면 손 냄새 맡게 하고 칭찬하기', 4, '강아지가 계속 떨며 힘들어하면 다가가 손 냄새를 맡게 하고 칭찬해 주세요. 잘하고 있다면 살짝 긁어 주는 것까지는 괜찮아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050505, 1060505, '보호자와 연결되는 롱리드 추가하기', 5, '고정된 줄에 더해, 보호자와 연결되는 긴 줄인 롱리드를 추가로 거세요. 강아지가 목줄을 물어뜯는 등 문제 행동을 보일 때 당겨서 제지할 수 있는 안전장치예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(106050506, 1060505, '같은 과정을 시간 들여 계속 반복하기', 6, '같은 과정을 계속 반복하세요. 오랜 시간이 필요해요. 핸드폰을 보거나 책을 읽으며 시간을 충분히 들이세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107010101, 1070101, '평생 산책을 좌우하는 첫 적응', 1, '어릴 때 가벼운 리드줄에 편안하게 적응하면 앞으로의 산책이 훨씬 즐거워져요. 작고 가벼운 나일론 목줄부터 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107010102, 1070101, '실내에서 계속 채워 두는 목줄', 2, '목에 가볍게 걸치고 실내에서 목줄을 계속 채워 두어 충분히 익숙해지게 해 주세요. 하루 중 대부분을 차고 있어도 신경 쓰지 않을 정도가 목표예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107010103, 1070101, '쓰면 안 되는 초크체인', 3, '당기면 목이 조이는 초크체인은 어떤 경우에도 사용하지 마세요. 장비가 조여질수록 흥분할 수 있으니 몸에 잘 맞는 편안한 목줄이나 하네스를 골라 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107010104, 1070101, '긁지 않고 움직이면 다음 단계', 4, '목줄을 긁거나 불편해하지 않고 자연스럽게 움직이면 다음 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107010201, 1070102, '줄을 매단 채 보내는 시간', 1, '가벼운 줄을 목줄에 매달고 줄을 단 채 혼자 다니게 두세요. 줄의 무게와 끌리는 느낌에 먼저 익숙해지는 단계예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107010202, 1070102, '이끌지 않고 따라가는 걷기', 2, '줄을 달고 중심 잡고 걷는 것이 익숙해지면 한쪽 끝을 잡고 넓은 공간에서 강아지가 가고자 하는 대로 천천히 따라가 주세요. 이끌려고 하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107010203, 1070102, '자연스럽게 걸으면 야외 단계로', 3, '줄을 단 상태에서도 자연스럽게 걷고 생활할 수 있으면 야외 산책 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107020101, 1070201, '통제가 아니라 함께 걷는 경험', 1, '줄로 억지로 통제하기보다 줄을 매고 함께 걷는 경험부터 알려 주세요. 어린 강아지가 가고 싶은 방향을 탐색할 시간도 충분히 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107020102, 1070201, '가자는 대로 따라가며 주는 먹이', 2, '줄을 매고 강아지가 가자는 대로 따라가며 먹이를 주세요. 저녁밥을 산책에서 다 줘도 괜찮고, 드러눕거나 버티면 강요하지 말고 먹이로 살살 유도해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107020103, 1070201, '쳐다보는 순간의 뒷걸음 보상', 3, '강아지가 보호자를 바라보는 순간 뒷걸음치며 간식을 주세요. 보호자에게 집중하면 좋은 일이 생긴다는 경험을 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107020104, 1070201, '막지 않고 옆에서 하는 이탈', 4, '돌이나 나뭇잎 냄새를 막지 말고 옆에 간식을 주어 자연스럽게 자리를 뜨게 해 주세요. 막는 것 자체가 잔소리가 되어 산책만 나가면 보호자를 보지 않게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107020105, 1070201, '산만하면 조용한 곳에서 재시도', 5, '산만해하면 자극이 적은 조용한 곳에서 거리를 좁혀 다시 시도해 주세요. 너무 잘해서 만져 주고 싶어도 이때는 만지지 않는 편이 좋아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107020201, 1070202, '한 자세를 오래 못 하는 대형견 퍼피', 1, '대형견 강아지는 성장 속도가 빨라 한 자세를 오래 유지하기 어려울 수 있어요. 정확한 동작을 요구하기보다 편안하게 앞으로 걷는 경험을 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107020202, 1070202, '움직일 때마다 주는 간식', 2, '보호자가 움직일 때마다 간식을 하나씩 주세요. 사선으로 걸어도 정상이니 걷는 것만으로 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107020203, 1070202, '얼굴을 들고 걷는 연습', 3, '얼굴을 들고 보호자를 보면서 걷는 연습도 함께 해 주세요. 시선이 위로 올라오면 앞으로의 줄 교육이 훨씬 쉬워져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107020204, 1070202, '이 정도만으로도 남는 도움', 4, '어린 시기에 줄을 따라 편안하게 걷는 경험만 만들어도 이후 교육에 도움이 돼요. 정확한 복종 동작은 이갈이가 끝난 뒤 천천히 시작해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107030101, 1070301, '오래 걷기가 아닌 차분해지는 연습', 1, '이 단계는 오래 걷는 연습이 아니에요. 바깥 자극을 안전한 거리에서 보고 다시 차분해지는 연습이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107030102, 1070301, '리드줄 뒤에도 필요한 기다림', 2, '리드줄을 채웠다고 바로 나가지 마세요. 문 앞에서 뛰어나가려 하면 멈추고 차분해졌을 때 조용히 나가 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107030103, 1070301, '현관에서 엘리베이터까지', 3, '처음부터 멀리 걷지 말고 현관, 복도, 엘리베이터 앞처럼 가까운 곳부터 경험하게 해 주세요. 각 장소에서 짧고 편안하게 머무는 것이 목표예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107030104, 1070301, '간식을 먹는지로 보는 난이도', 4, '그 자리에서 간식을 먹고 보호자를 다시 볼 수 있으면 적당한 난이도예요. 간식을 먹지 못하면 긴장이 높다는 뜻이니 더 조용한 장소로 돌아가 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107030105, 1070301, '접종 전 바닥 접촉 주의', 5, '접종 전에는 개가 많이 다니는 바닥에 내려놓지 마세요. 안거나 이동장으로 소리와 움직임을 짧게 경험시키고, 모르는 개와의 만남이나 애견카페는 피해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107030201, 1070302, '보이면 바로 가지 않는 거리', 1, '사람이나 차, 자전거, 다른 강아지가 보이면 바로 가까이 가지 마세요. 짖거나 달려들기 전에 거리를 벌리고 멀리서 차분히 바라보게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107030202, 1070302, '다시 보호자를 보면 주는 칭찬', 2, '자극을 봤다가 보호자를 다시 보면 짧게 칭찬하고 작은 간식을 주세요. 간식을 먹지 못하거나 아예 보호자를 보지 못하면 그 거리는 아직 어려우니 다시 볼 수 있는 거리까지 물러나 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107030203, 1070302, '꼬리 말기와 얼어붙기가 뜻하는 것', 3, '꼬리를 말거나 얼어붙거나 계속 짖는다면 자극이 너무 가까운 거예요. 버티게 하지 말고 몇 걸음 물러나 짧게 끝내 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107030204, 1070302, '공격성이 아니라 거리 부족', 4, '짖거나 몸이 굳는 모습은 공격성보다 거리가 너무 가깝다는 신호일 수 있어요. 감당할 수 있는 거리로 물러나 차분해질 시간을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040101, 1070401, '자극에 쏠린 집중의 분산', 1, '주변 자극에만 향한 관심을 보호자에게 조금씩 나눠 주세요. 줄을 느슨하게 유지하고 보호자의 움직임을 바라보는 순간 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040102, 1070401, '한 발짝 움직이며 주는 신호', 2, '줄을 매고 한 발짝 움직인 뒤 같이 움직이면 보상해 주세요. 움직이지 않는 것은 쉬는 것이 아니라 자극에 달려들 준비일 수 있으니, 가벼운 신호를 주고 보호자가 움직이면 함께 움직인다는 것을 알려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040103, 1070401, '멈춤과 출발의 명확한 타이밍', 3, '보호자가 멈추면 함께 멈추고 움직이면 따라오는 연습을 반복해 주세요. 줄은 위로 들지 말고 낮게 유지하며, 따라오면 바로 칭찬하고 간식을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040104, 1070401, '거실에서 시작하는 느슨한 줄', 4, '거실에 먹을 것을 두고 줄이 느슨한 상태로 함께 이동해 도착하면 먹게 해 주세요. 줄이 팽팽한 채 끌려가서 먹는 방식이 되지 않게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040201, 1070402, '자극이 적은 조용한 공원', 1, '흥미 요소가 적고 산만하지 않은 조용한 공원을 골라 주세요. 사람이 많은 길은 피해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040202, 1070402, '말없이 걷는 리더워크', 2, '줄을 조금 느슨하게 둔 채 말없이 걸어 보세요. 계속 쳐다보거나 끌지 말고 보호자의 움직임을 자연스럽게 따라오게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040203, 1070402, '당기면 말없이 반대 방향으로', 3, '줄을 팽팽히 당겨 뛰쳐나가면 즉시 말없이 반대 방향으로 걸어 주세요. 또 당기면 또 반대 방향으로 가는 이 과정이 핵심이고, 처음에는 100m도 못 갈 수 있지만 끈기 있게 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040204, 1070402, '멈췄다 느슨해지면 다시 걷기', 4, '줄을 당기면 그 자리에서 멈추고, 돌아보며 줄이 느슨해지면 다시 걸어 주세요. 사용할 말과 행동을 가족 모두가 같게 유지해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040205, 1070402, '돌아보며 길을 찾으면 성공', 5, '줄을 당기지 않고 보호자를 돌아보며 길을 찾으면 잘하고 있는 거예요. 한 번 익히면 평생 쓰는 습관이 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040301, 1070403, '자극이 없어서 잘 걷는 경우', 1, '평소에는 잘 걷더라도 자극이 나타나면 달려들 수 있어요. 자극이 없는 순간부터 줄을 느슨하게 유지하는 습관을 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040302, 1070403, '보도블록 선을 활용한 신호', 2, '보도블록의 선이 다가오면 가벼운 신호를 한 번 주고 보호자가 먼저 선을 밟아 주세요. 선마다 반복하면 그 간격마다 보호자를 쳐다보게 되어 자극에 대한 집중이 깨져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040303, 1070403, '강아지가 있는 쪽으로의 양보', 3, '사람이 마주 오면 항상 강아지가 있는 쪽으로 비켜 주세요. 반대쪽으로 피하면 지나간 사람의 뒷모습이 도망가는 것처럼 보여 자신감이 붙고 더 짖게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040304, 1070403, '자극에 따라 나누는 냄새 시간', 4, '자극이 없을 때는 산책로 가운데로 걸어 주세요. 자극이 나타나면 가장자리에서 냄새를 맡게 해 집중을 분산시켜 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040401, 1070404, '산책보다 먼저인 리드 트레이닝', 1, '대형견은 힘이 세서 산책보다 리드 트레이닝이 먼저예요. 줄을 다루는 기본이 잡힌 뒤에 거리를 늘려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040402, 1070404, '치고 나갈 때의 멈춤', 2, '앞으로 치고 나가면 바로 멈춰 주세요. 보호자를 돌아보고 줄이 느슨해지면 한두 발짝 뒤로 움직인 뒤 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040403, 1070404, '줄을 짧게 잡고 하는 회전', 3, '줄을 짧게 잡고 보호자와 함께 좌우로 도는 연습을 해 주세요. 출발할 때는 강아지 앞을 부드럽게 가로막으며 방향을 알려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040404, 1070404, '방향 전환과 멈춤마다 주는 간식', 4, '방향을 바꾸거나 멈춘 순간마다 간식을 하나씩 주세요. 보호자와 눈을 맞추면 바로 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107040405, 1070404, '줄을 놓치거나 넘어질 위험', 5, '줄을 놓치거나 넘어지면 사람과 강아지 모두 위험해요. 뛰어서 에너지를 빼는 방식은 특히 조심해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107050101, 1070501, '세 살까지 들고 다니는 간식', 1, '산책할 때는 꼭 간식을 들고 다녀 주세요. 세 살까지는 필수이고, 강아지가 보지 않아도 먹이를 주면서 시작해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107050102, 1070501, '점프할 때 내는 낯선 소리', 2, '점프하면 평소와 다른 짧은 소리로 멈춰야 한다는 것을 알려 주세요. 멈춘 순간에는 "옳지"라고 같은 말로 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107050103, 1070501, '먹자마자 일어나는 강아지', 3, '간식을 먹자마자 일어난다면 먹는 동안 줄을 살짝 유지해 앉은 자세를 이어가게 해 주세요. 준비 시간을 줄이도록 스틱형 간식을 미리 잘라 두세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107050104, 1070501, '다음 신호까지 유지하는 자세', 4, '"앉아" 다음 신호가 올 때까지 자세를 유지하는 것이 핵심이에요. 말을 반복하기보다 줄과 표정, 몸짓으로 차분하게 안내해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107050105, 1070501, '의자에 앉으면 옆에 엎드리는 자세', 5, '먹이로 의자까지 유도한 뒤 "기다려"를 시키고, 앉으면 어깨죽지를 살짝 눌러 천천히 엎드리게 해 주세요. 먹이는 앞다리 사이 바닥에 주고, 버티면 억지로 누르지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107050106, 1070501, '앉으면 엎드리는 습관', 6, '엎드려 있을 때만 먹이가 계속 나오게 하면 보호자가 앉으면 나도 엎드린다는 것을 배워요. 마무리는 재밌게 놀아 주며 끝내 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107060101, 1070601, '호기심이 많아지는 4개월', 1, '생후 4개월 무렵에는 호기심이 많아 지나가는 대상에 쉽게 반응해요. 다른 사람과 강아지를 배려하며 기다리는 산책 예절을 알려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107060102, 1070601, '모두에게 달려가지 않는 규칙', 2, '모든 사람에게 달려가 인사하게 두지 마세요. 보호자가 허락한 경우에만 다가가도록 하고, 멈추면 바로 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107060103, 1070601, '아는 사람을 만났을 때', 3, '아는 사람을 만나면 거리를 둔 채 "기다려"를 시켜 주세요. 상대가 먼저 지나간 뒤 칭찬하고 출발하면 갑자기 달려드는 행동을 줄일 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107060104, 1070601, '먼저 비켜 주는 배려', 4, '지나가는 사람이 있으면 줄을 짧게 잡고 보호자가 미리 비켜 주세요. 치고 나가려 하면 빠르게 줄을 따라 들어가 강아지 앞을 막아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107060105, 1070601, '멀찍이 기다리는 다른 개와의 만남', 5, '다른 강아지를 만나면 멀리서 기다리며 차분히 바라보게 해 주세요. 보호자가 허락하기 전까지 기다릴 수 있으면 충분히 잘한 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070101, 1070701, '지루한 산책이 부르는 짖음', 1, '냄새만 맡고 뒤따라가는 산책은 강아지에게 지루해요. 지루하면 다른 자극을 찾아 짖게 되니 산책에 변화를 넣어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070102, 1070701, '의자와 기둥으로 만드는 코스', 2, '공원의 의자와 기둥을 작은 코스처럼 활용해 함께 걸어 보세요. 중간마다 "이리 와"라고 부르고 따라오면 바로 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070103, 1070701, '바닥 선과 나무 사이의 변화', 3, '바닥 선 안에서 "기다려"를 시키거나 나무 사이를 통과하고, 특정 블록 위에 간식을 두는 변화를 줘 보세요. 계단은 위에서 내려오는 것부터 알려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070104, 1070701, '울퉁불퉁하고 경사 있는 길', 4, '매끄러운 길보다 울퉁불퉁하고 오르막과 내리막이 있는 길이 훨씬 좋아요. 시각적 변화가 많아 덜 지루해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070201, 1070702, '줄에 익숙하지 않은 것이 원인', 1, '주저앉는 원인은 대개 목줄과 줄에 익숙하지 않은 거예요. 멀리서 부르거나 안아 옮기기를 반복하면 그 패턴이 굳어져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070202, 1070702, '집에서 익히는 줄의 긴장감', 2, '집에서 줄을 매고 보호자가 주변을 움직이며 줄이 조여지고 팽팽해지는 느낌에 익숙해지게 해 주세요. 가자고 하며 확 당기지 마세요. 당기면 더 버텨요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070203, 1070702, '한 발짝씩 주는 신호', 3, '한 발짝씩 가벼운 신호를 주며 움직이고, 한 걸음이라도 움직이면 그대로 이어 가 주세요. 정지한 채 마주 서지 말고 항상 가는 방향을 보여 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070204, 1070702, '버틸 때 쓰는 몸의 힘', 4, '버티면 줄을 짧게 잡고 쳐다보지 않은 채 몸으로 가볍게 밀어 주세요. 엎드려 버티면 가슴 사이에 발을 살짝 넣어 일어나도록 유도해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070205, 1070702, '줄을 물고 당기며 놀 때', 5, '줄을 물고 당기며 노는 것은 보호자도 함께 당기고 있기 때문이에요. 줄 잡은 손을 몸에 붙이고 멈추면 흥미를 잃고, 놓았을 때 칭찬한 뒤 산책과 놀이를 구분해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070301, 1070703, '걷기가 아닌 바깥의 즐거움', 1, '산책의 목적을 걷기가 아니라 바깥이 좋은 곳임을 알려주는 데 두세요. 거리를 늘리는 것은 그다음이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070302, 1070703, '안고 기다리는 1단계 적응', 2, '길거리에서 편안하게 앉아 있는 모습이 보일 때까지 안고 기다려 주세요. 매일 같은 자리에 나와 익숙해지게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070303, 1070703, '긴 줄로 스스로 나아가는 2단계', 3, '앞에서 끌면 버티니 줄을 길게 두고 스스로 나아가는 만큼만 따라가 주세요. 멈춰 있다면 판단하는 중이니 기다려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070304, 1070703, '못 넘는 지점에서의 방향 전환', 4, '넘지 못하는 지점이 있다면 앞에서 끌지 마세요. 지나온 방향으로 돌아가 뒤쪽에서 부르면 조금 더 편안하게 움직일 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070305, 1070703, '충전과 방전의 반복', 5, '한계점까지 갔다가 지치면 품에서 쉬게 하고 다시 나아가기를 반복해 주세요. 이 과정에서 자신감이 올라가고 어릴 때의 좋은 기억은 평생 남아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070401, 1070704, '일정한 속도로 도는 느린 산책', 1, '소심한 강아지와는 일정한 속도로 천천히 원을 그리며 걸어 주세요. 줄을 느슨하게 유지하고 충분히 냄새 맡을 시간을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070402, 1070704, '속도가 빨라지면 브레이크', 2, '차분히 냄새를 맡으면 그대로 두고, 속도가 갑자기 빨라지면 잠시 멈춰 주세요. 빨리 냄새를 맡는 것은 해소가 아니라 빨리 벗어나고 싶다는 두려움의 표현이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070403, 1070704, '소리에 놀랐을 때의 반응', 3, '소리에 놀라도 보호자는 같이 놀라지 마세요. 줄만 잡고 가만히 있다가 다시 냄새를 맡기 시작하면 출발해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070404, 1070704, '의자에 앉아 머무는 시간', 4, '산책 중간에 의자에 앉아 주변에서 잠시 머물러 주세요. 편안하게 머문 장소가 늘어나면 강아지의 자신감도 함께 커져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070405, 1070704, '자신감이 높은 개에게는 주의', 5, '이 노즈워크는 소심한 강아지의 자신감을 키우기 위한 방법이에요. 영역을 주장하거나 공격성이 있어 자신감이 이미 높은 강아지에게는 오히려 강해질 수 있으니 주의해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070501, 1070705, '흥분을 빠르게 가라앉힐 수단', 1, '산책 중 흥분이 폭발했을 때 빠르게 진정시킬 수단을 미리 만들어 두는 단계예요. 발산과 진정을 한 세트로 연습해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070502, 1070705, '제한된 상태에서 하는 발산', 2, '단단한 나무에 줄을 묶고 터그와 간식으로 일부러 최대한 흥분시켜 에너지를 발산시켜 주세요. 행동이 제한된 상태에서 흥분을 폭발시키면 에너지가 더 쉽게 빠져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070503, 1070705, '쉬는 시간에 배우는 진정', 3, '놀이 중 쉬는 시간에는 "그만"이라고 말하고 차분해질 시간을 주세요. 잘 기다리면 다시 신나게 놀아주는 것으로 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070504, 1070705, '올라탈 때 피하지 않는 대응', 4, '몸에 올라타도 바로 피하지 말고 차분히 멈춰 주세요. 피할수록 더 올라타니 진정할 때까지 기다리되 줄이 몸에 감기지 않도록 주의해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(107070505, 1070705, '차분해지면 나가는 산책', 5, '충분히 발산해 차분해지면 산책을 나가 주세요. 밖에서 다시 흥분하면 튼튼한 나무에 묶어 한 번 더 발산시키고 가라앉으면 이어서 걸어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108010101, 1080101, '평생 가장 편안해지는 장소', 1, '켄넬은 가두는 수단이 아니라 잘 익숙해지면 평생 가장 편안함을 느끼는 장소가 돼요. 억지로 밀어 넣거나, 혼내는 장소로 쓰거나, 심하게 불안해할 때까지 버티게 하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108010102, 1080101, '가족이 보이지만 조용한 자리', 2, '가족의 움직임이 보이지만 시끄럽지 않은 곳에 켄넬을 두세요. 문은 열어두고 미끄럽지 않은 담요를 깔아 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108010103, 1080101, '밀어 넣지 않는 첫 만남', 3, '켄넬 안으로 억지로 밀어 넣지 마세요. 스스로 냄새를 맡고 입구를 살펴보게 두고, 경계가 심하면 며칠 동안 근처를 지나는 경험부터 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108010104, 1080101, '스스로 탐색하면 다음 단계', 4, '도움 없이 스스로 켄넬에 다가가 냄새를 맡고 안을 살펴볼 수 있으면 다음 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108020101, 1080201, '갇히는 곳이 아닌 드나드는 곳', 1, '켄넬에 들어가면 갇힌다는 느낌보다 자유롭게 드나드는 경험을 먼저 만들어 주세요. 켄넬과 작은 간식을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108020102, 1080201, '켄넬 앞에 떨어뜨리는 간식', 2, '간식을 켄넬 앞에 떨어뜨려 근처까지만이라도 가까이 가게 해 주세요. 들어가는 것보다 다가가는 것이 먼저예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108020103, 1080201, '안에서 하나, 밖에서 하나', 3, '들어가면 얼굴 앞에 간식을 하나 주고 밖에도 하나를 떨어뜨려 주세요. 자연스럽게 나오도록 유도해 드나드는 경험을 만드는 방법이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108020104, 1080201, '안 나오고 기다릴 때', 4, '나오지 않고 기다린다면 그냥 얼굴 앞에 간식을 주면 돼요. 반드시 나와야 성공인 것이 아니라 안에서 편안히 기다리는 것도 좋은 상태예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108020105, 1080201, '간식을 들면 먼저 들어가면 성공', 5, '간식을 든 보호자가 켄넬 옆에 갔을 때 스스로 안으로 들어가면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108030101, 1080301, '조금씩 늘리는 머무는 시간', 1, '켄넬 안에서 편안하게 머무는 시간을 조금씩 늘려 주세요. 가장 좋아하는 간식과 장난감, 오래 먹을 수 있는 간식을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108030102, 1080301, '켄넬 안에서만 주는 특별 간식', 2, '가장 좋아하는 간식은 켄넬 안에서만 주세요. 강압 없이도 스스로 들어가 기다리게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108030103, 1080301, '자꾸 넣어 두는 좋아하는 장난감', 3, '좋아하는 장난감을 켄넬 안에 자주 넣어 두세요. 가끔 안쪽에 땅콩버터를 발라 두면 우연히 발견해 핥으며 여기 들어가면 늘 좋은 일이 생긴다고 배워요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108030104, 1080301, '오래 먹는 간식으로 늘리는 시간', 4, '드나들기가 잘 되면 개껌처럼 오래 먹는 간식을 안에서 주세요. 오래 머물다 보면 그 공간을 좋아하게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108030105, 1080301, '스스로 들어가기 시작하면 다음 단계', 5, '보상 없이도 스스로 크레이트 안으로 들어가기 시작하면 다음 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108040101, 1080401, '문이 닫혀도 괜찮다는 경험', 1, '문이 닫혀도 나쁜 일이 아니라는 경험을 만드는 단계예요. 아주 짧은 시간부터 시작해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108040102, 1080401, '스스로 들어갔을 때의 짧은 닫힘', 2, '스스로 들어갔을 때 문을 아주 잠깐 닫아 보세요. 나오고 싶어 하기 전에 다시 열어 편안한 경험으로 끝내 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108040103, 1080401, '나오려 할 때 바로 여는 문', 3, '간식이나 껌을 다 먹고 나오려 하면 문을 바로 열어 주세요. 지체하면 켄넬이 답답한 곳으로 기억돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108040104, 1080401, '불안해하지 않으면 다음 단계', 4, '문을 닫아도 불안해하지 않고 스스로 크레이트에 자주 들어가면 다음 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108050101, 1080501, '동작이 먼저, 신호는 나중에', 1, '동작이 확실해진 뒤에 신호를 입혀야 해요. 처음부터 "하우스"라고 말하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108050102, 1080501, '들어가고 싶은 마음', 2, '켄넬 안에 간식을 넣어 스스로 들어가고 싶게 만들어 주세요. 들어가려는 순간에만 "하우스"라고 짧게 말해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108050103, 1080501, '들어갈 때마다 붙이는 한마디', 3, '들어갈 때마다 "하우스"라고 한마디를 붙여 주세요. 반복되면 그 말 한마디에 스스로 들어가 보상을 기다려요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(108050104, 1080501, '한마디에 들어가면 완성', 4, '"하우스"라는 말 한마디에 스스로 켄넬에 들어가 보상을 기다리면 이 주제를 마친 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(109010101, 1090101, '시작하기', 1, 'V 손신호를 시도하기 전에 보호자의 손바닥 위에 턱을 올리는 동작부터 먼저 연습해봐요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(109010102, 1090101, '준비물', 2, '자극이 적고 미끄럽지 않은 곳에서 간식을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(109010103, 1090101, '손바닥 내밀기', 3, '간식을 쥐지 않은 손바닥을 위로 펴서 강아지 턱보다 조금 아래에 내밀어주세요.
