-- 프론트엔드에 노출되는 백엔드 정적 훈련 초기 데이터.
-- 대상 스키마는 Meongcoach.sql보다 백엔드 JPA 엔티티를 우선한다.
-- 2026-09-04 dev DB(meongcoach-dev-db)의 training_categories·topics·curriculums·lessons·cards·card_media를 그대로 내보냈다. 시각 컬럼만 CURRENT_TIMESTAMP로 둔다.
-- Counts: categories=5, topics=12, curriculums=57, lessons=133, cards=644, cardMedia=144.
BEGIN;

DELETE FROM "card_branches"
WHERE "card_id" IN (
	SELECT "cards"."id"
	FROM "cards"
	JOIN "lessons" ON "lessons"."id" = "cards"."lesson_id"
	JOIN "curriculums" ON "curriculums"."id" = "lessons"."curriculum_id"
	WHERE "curriculums"."topic_id" = 106
)
OR "next_card_id" IN (
	SELECT "cards"."id"
	FROM "cards"
	JOIN "lessons" ON "lessons"."id" = "cards"."lesson_id"
	JOIN "curriculums" ON "curriculums"."id" = "lessons"."curriculum_id"
	WHERE "curriculums"."topic_id" = 106
)
OR "card_id" IN (109010104, 109010106, 109020106, 109020206)
OR "next_card_id" IN (109010104, 109010106, 109020106, 109020206);
DELETE FROM "card_media" WHERE "card_id" IN (109010104, 109010106, 109020106, 109020206);
DELETE FROM "card_media"
WHERE "card_id" IN (
	SELECT "cards"."id"
	FROM "cards"
	JOIN "lessons" ON "lessons"."id" = "cards"."lesson_id"
	JOIN "curriculums" ON "curriculums"."id" = "lessons"."curriculum_id"
	WHERE "curriculums"."topic_id" = 106
);
DELETE FROM "cards" WHERE "id" IN (106010105, 109010104, 109010106, 109020106, 109020206);

ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "icon_url" = EXCLUDED."icon_url", "sort_order" = EXCLUDED."sort_order", "updated_at" = CURRENT_TIMESTAMP;

